-- ─── LESSONS + EVALUATIONS ───────────────────
INSERT INTO lessons (id, user_id, group_name, topic, course_type, duration_seconds, transcript, created_at) VALUES (1000, 1000, 'DI-101', 'DA — Yechimlar muhokamasi', 'Dasturlash asoslari', 2148, 'Bugun shartli operatorlar mavzusiga to''xtalamiz. Dastur har doim chiziqli bajarilmaydi — ba''zan biz uning yo''nalishini boshqarishimiz kerak. Buning uchun if konstruksiyasidan foydalanamiz.

Sintaksisi juda oddiy: if shart, keyin ikki nuqta, va keyingi qatorda tabulyatsiya bilan bajariladigan kod. Misol: if yosh >= 18: print("Voyaga yetgan"). Agar shart bajarilmasa, else bloki ishlaydi.

Bir nechta shartlarni tekshirish uchun elif kalit so''zi bor. Masalan: if score >= 90 print("a''lo"), elif score >= 70 print("yaxshi"), else print("qoniqarli"). Ushbu konstruksiya darslar bahosini aniqlash uchun ko''p ishlatiladi.

Operator and, or, not yordamida murakkab shartlar tuzish mumkin. Eslatib o''taman: Python da indentatsiya juda muhim — agar bo''shliqlar to''g''ri qo''yilmasa, dastur xato beradi.', '2026-07-07 09:46:00');
INSERT INTO evaluations (lesson_id, overall_score, topic_score, speech_score, method_score, interaction_score, feedback_score, summary, strengths, improvements, advice, created_at) VALUES (1000, 87, 20, 16, 16, 15, 20, 'Dars yaxshi tashkil etilgan, mavzu chuqur va aniq yoritilgan. O''quvchilar bilan muloqot mustahkam.', '["Real hayotdagi misollar yordamida nazariya mustahkamlandi.","Misollar amaliy va o''quvchilarga tushunarli.","Vizual yoki yozma misollar kontsentratsiyaga yordam berdi."]', '["Murakkab atamalar uchun qisqacha takror berib turish foydali.","Yozma misollarni daftar yoki taxta orqali ko''rsatish.","Ko''proq amaliy mashqlar berilsa yaxshi bo''lardi."]', '["Darsda Q&A vaqti aniq belgilash — talabalar savol berishdan tortinmasin.","Uy vazifasi sifatida 2-3 ta savol berish va keyingi darsda ko''rib chiqish.","Eng oddiy misoldan boshlab keyingi qadamga o''tish — barcha o''quvchilar bilan bir tezlikda yurishga yordam beradi."]', '2026-07-07 09:46:00');
INSERT INTO lessons (id, user_id, group_name, topic, course_type, duration_seconds, transcript, created_at) VALUES (1001, 1000, 'DI-101', 'DA — Takrorlash va xulosa', 'Dasturlash asoslari', 2169, 'Salom o''quvchilar. Bugungi darsimizda biz o''zgaruvchilar va ularning turlari haqida gaplashamiz. O''zgaruvchi — bu ma''lumotni saqlash uchun nomli xotira maydoni. Python tilida o''zgaruvchini e''lon qilish uchun ismni yozib, teng belgisidan keyin qiymatni kiritamiz.

Misol uchun: yosh = 20. Bu yerda yosh degan o''zgaruvchiga 20 qiymati berildi. Endi keling turlarga e''tibor beraylik. Asosan to''rtta turdagi ma''lumot bor: int — butun sonlar, float — kasr sonlar, str — matn, va bool — rost yoki yolg''on qiymatlar.

Type funksiyasi orqali o''zgaruvchining turini bilib olishimiz mumkin. Print(type(yosh)) deb yozsak, ekranda class int chiqadi. Bu Python avtomatik ravishda turini aniqlaganini ko''rsatadi.

Endi sizga vazifa: o''z ismingiz va yoshingizni ifodalaydigan ikki o''zgaruvchi yarating va ekranga chiqaring. Keyingi darsda biz shartli operatorlarni o''rganamiz.', '2026-07-01 11:42:00');
INSERT INTO evaluations (lesson_id, overall_score, topic_score, speech_score, method_score, interaction_score, feedback_score, summary, strengths, improvements, advice, created_at) VALUES (1001, 59, 10, 10, 14, 11, 14, 'Tushuntirish nomuvofiq, ba''zi muhim joylar o''tkazib yuborildi.', '["Real hayotdagi misollar yordamida nazariya mustahkamlandi.","Mavzu aniq va izchil yoritildi.","Vizual yoki yozma misollar kontsentratsiyaga yordam berdi."]', '["Murakkab atamalar uchun qisqacha takror berib turish foydali.","Tezlikni biroz pasaytirish — ayrim joylar tez o''tib ketdi.","O''quvchilarga savollar berib qatnashtirish keng bo''lishi kerak."]', '["Eng oddiy misoldan boshlab keyingi qadamga o''tish — barcha o''quvchilar bilan bir tezlikda yurishga yordam beradi.","Darsda Q&A vaqti aniq belgilash — talabalar savol berishdan tortinmasin."]', '2026-07-01 11:42:00');
INSERT INTO lessons (id, user_id, group_name, topic, course_type, duration_seconds, transcript, created_at) VALUES (1002, 1000, 'DI-101', 'DA — Yangi mavzu kirishi', 'Dasturlash asoslari', 3031, 'Bugun shartli operatorlar mavzusiga to''xtalamiz. Dastur har doim chiziqli bajarilmaydi — ba''zan biz uning yo''nalishini boshqarishimiz kerak. Buning uchun if konstruksiyasidan foydalanamiz.

Sintaksisi juda oddiy: if shart, keyin ikki nuqta, va keyingi qatorda tabulyatsiya bilan bajariladigan kod. Misol: if yosh >= 18: print("Voyaga yetgan"). Agar shart bajarilmasa, else bloki ishlaydi.

Bir nechta shartlarni tekshirish uchun elif kalit so''zi bor. Masalan: if score >= 90 print("a''lo"), elif score >= 70 print("yaxshi"), else print("qoniqarli"). Ushbu konstruksiya darslar bahosini aniqlash uchun ko''p ishlatiladi.

Operator and, or, not yordamida murakkab shartlar tuzish mumkin. Eslatib o''taman: Python da indentatsiya juda muhim — agar bo''shliqlar to''g''ri qo''yilmasa, dastur xato beradi.', '2026-06-06 11:45:00');
INSERT INTO evaluations (lesson_id, overall_score, topic_score, speech_score, method_score, interaction_score, feedback_score, summary, strengths, improvements, advice, created_at) VALUES (1002, 69, 11, 16, 13, 15, 14, 'O''rtacha sifatdagi dars — mavzu qamrab olindi, lekin o''quvchilar reaktsiyasiga ko''p e''tibor berilmadi.', '["O''quvchilar bilan o''zaro muloqot yaxshi tashkil etilgan.","Tushunchalar bosqichma-bosqich oddiydan murakkabga qarab tushuntirildi."]', '["Yozma misollarni daftar yoki taxta orqali ko''rsatish.","Dars oxirida qisqa xulosa va kalit fikrlarni qaytarish."]', '["Tinglovchilarga 5-7 daqiqada bir savol berish — diqqatni saqlaydi.","Muhim atamalarni taxtaga yozib qo''yish — eslab qolishni osonlashtiradi."]', '2026-06-06 11:45:00');
INSERT INTO lessons (id, user_id, group_name, topic, course_type, duration_seconds, transcript, created_at) VALUES (1003, 1000, 'DI-101', 'DA — Test va o''zlashtirish', 'Dasturlash asoslari', 1051, 'Funksiyalar — bu kodni qayta ishlatish uchun asosiy vosita. def kalit so''zi bilan funksiyani aniqlaymiz. Argumentlar qavslar ichida, return orqali qiymat qaytariladi.

Misol uchun, ikki sonni qo''shadigan funksiya: def yigindi(a, b): return a + b. Endi bu funksiyani istalgan joyda chaqirsak bo''ladi: natija = yigindi(5, 3). Bu yerda 8 qaytariladi.

Default argumentlar ham mavjud. Agar argument berilmasa, default qiymat ishlatiladi. Misol: def salom(ism="dunyo"): print("Salom", ism). Salom() chaqirilganda "Salom dunyo" chiqadi.

Funksiya nomlari mazmunli bo''lishi kerak. yigindi, ko_paytma, foiz_hisobla — bularning hammasi yaxshi nomlar. f1, x, abc — yomon nomlar. Yaxshi kod yozish — bu o''qilishi oson kod yozish.', '2026-06-08 13:32:00');
INSERT INTO evaluations (lesson_id, overall_score, topic_score, speech_score, method_score, interaction_score, feedback_score, summary, strengths, improvements, advice, created_at) VALUES (1003, 82, 14, 18, 20, 17, 13, 'Dars yaxshi tashkil etilgan, mavzu chuqur va aniq yoritilgan. O''quvchilar bilan muloqot mustahkam.', '["O''quvchilar bilan o''zaro muloqot yaxshi tashkil etilgan.","Vizual yoki yozma misollar kontsentratsiyaga yordam berdi."]', '["Yozma misollarni daftar yoki taxta orqali ko''rsatish.","Murakkab atamalar uchun qisqacha takror berib turish foydali."]', '["Real loyiha yoki amaliy vazifa qo''shish — motivatsiyani oshiradi.","Uy vazifasi sifatida 2-3 ta savol berish va keyingi darsda ko''rib chiqish.","Har dars boshida 1-2 daqiqa o''tgan darsni qaytarish — yaxshi natija beradi."]', '2026-06-08 13:32:00');
INSERT INTO lessons (id, user_id, group_name, topic, course_type, duration_seconds, transcript, created_at) VALUES (1004, 1003, 'DI-101', 'MD — Yechimlar muhokamasi', 'Mobil dasturlash', 3023, 'Android Compose — bu zamonaviy UI yaratish texnologiyasi. XML layout o''rniga biz Kotlin tilida deklarativ tarzda interfeysni tasvirlaymiz.

@Composable annotatsiyasi orqali funksiyalar yaratamiz. Misol: Text("Salom"), Button(onClick = ...), Column { Text(...); Text(...) }. State o''zgartirilganda UI avtomatik qayta render bo''ladi.

Modifier orqali ko''rinishni o''zgartiramiz: padding, background, clickable. Modifier zanjiri tartibi muhim — masalan padding(16.dp).background(Red) va background(Red).padding(16.dp) farqli natija beradi.

remember va mutableStateOf state boshqarish uchun. var count by remember mutableStateOf(0) — bu o''zgartirilganda UI yangilanadi. Ko''p ishlatiladigan pattern: Hoist state up, ya''ni state ni yuqori komponentga ko''chirish.', '2026-05-30 17:39:00');
INSERT INTO evaluations (lesson_id, overall_score, topic_score, speech_score, method_score, interaction_score, feedback_score, summary, strengths, improvements, advice, created_at) VALUES (1004, 59, 14, 10, 11, 10, 14, 'Dars sxematik o''tdi — o''quvchilar bilan muloqot deyarli yo''q edi.', '["Ovoz baland va aniq, jaranglashi yaxshi.","O''qituvchi savollarga aniq javob berdi.","Vizual yoki yozma misollar kontsentratsiyaga yordam berdi."]', '["Tezlikni biroz pasaytirish — ayrim joylar tez o''tib ketdi.","Ko''proq amaliy mashqlar berilsa yaxshi bo''lardi.","Tushuntirish boshlanishida darsning maqsadi aniq aytilishi kerak."]', '["Eng oddiy misoldan boshlab keyingi qadamga o''tish — barcha o''quvchilar bilan bir tezlikda yurishga yordam beradi.","Uy vazifasi sifatida 2-3 ta savol berish va keyingi darsda ko''rib chiqish.","Muhim atamalarni taxtaga yozib qo''yish — eslab qolishni osonlashtiradi."]', '2026-05-30 17:39:00');
