INSERT INTO lessons (id, user_id, group_name, topic, course_type, duration_seconds, transcript, created_at) VALUES (1011, 1004, 'DI-102', 'SIA — Misollar va tahlil', 'Sun''iy intellekt asoslari', 3735, 'Sun''iy intellekt nima va nima emas? Bugun biz aniq belgilab olamiz. AI — bu kompyuter sistemalari odam aql talab qiladigan vazifalarni bajarishi. Lekin bu film kabi sezuvchi mavjudot emas.

AI ning uch katta turi bor: tor AI (narrow) — bitta vazifani bajaruvchi, masalan shaxmat dasturi yoki yuzni tanish. Umumiy AI (AGI) — odam kabi har xil vazifalarni bajarish, hozircha mavjud emas. Super AI — odamdan o''tib ketish, faqat fantastikada.

Bugungi barcha mashhur tizimlar — ChatGPT, Gemini, Midjourney — tor AI. Ular ma''lum vazifaga juda yaxshi javob beradi, lekin tushunish va ong yo''q. Asosida statistika va naqshlarni topish.

Mashinaviy o''rganish — bu AI ni yaratishning asosiy yo''li. Dasturchi qoidalarni yozmaydi, balki misollar beradi va sistema o''zi naqshni topadi. Keyingi darsda biz neyron tarmoqlar haqida gaplashamiz.', '2026-06-04 09:29:00');
INSERT INTO evaluations (lesson_id, overall_score, topic_score, speech_score, method_score, interaction_score, feedback_score, summary, strengths, improvements, advice, created_at) VALUES (1011, 66, 14, 12, 14, 13, 13, 'Asosiy mavzu yetkazildi, lekin tushuntirishda ba''zi joylar tezroq o''tib ketdi.', '["Vizual yoki yozma misollar kontsentratsiyaga yordam berdi.","Ovoz baland va aniq, jaranglashi yaxshi."]', '["Murakkab atamalar uchun qisqacha takror berib turish foydali.","Yozma misollarni daftar yoki taxta orqali ko''rsatish.","Tezlikni biroz pasaytirish — ayrim joylar tez o''tib ketdi."]', '["Muhim atamalarni taxtaga yozib qo''yish — eslab qolishni osonlashtiradi.","Eng oddiy misoldan boshlab keyingi qadamga o''tish — barcha o''quvchilar bilan bir tezlikda yurishga yordam beradi.","Darsda Q&A vaqti aniq belgilash — talabalar savol berishdan tortinmasin."]', '2026-06-04 09:29:00');
