INSERT INTO evaluations (lesson_id, overall_score, topic_score, speech_score, method_score, interaction_score, feedback_score, summary, strengths, improvements, advice, created_at) VALUES (1016, 78, 14, 17, 18, 15, 14, 'O''rtacha sifatdagi dars — mavzu qamrab olindi, lekin o''quvchilar reaktsiyasiga ko''p e''tibor berilmadi.', '["Ovoz baland va aniq, jaranglashi yaxshi.","O''qituvchi savollarga aniq javob berdi.","O''quvchilar bilan o''zaro muloqot yaxshi tashkil etilgan."]', '["Ko''proq amaliy mashqlar berilsa yaxshi bo''lardi.","Yozma misollarni daftar yoki taxta orqali ko''rsatish."]', '["Real loyiha yoki amaliy vazifa qo''shish — motivatsiyani oshiradi.","Har dars boshida 1-2 daqiqa o''tgan darsni qaytarish — yaxshi natija beradi."]', '2026-07-12 15:38:00');
INSERT INTO lessons (id, user_id, group_name, topic, course_type, duration_seconds, transcript, created_at) VALUES (1017, 1005, 'DI-102', 'MO — Yangi mavzu kirishi', 'Mashinaviy o''rganish', 1776, 'Linear regressiya — eng oddiy va eng asosiy ML algoritm. Maqsadi: kirish (X) va chiqish (y) o''rtasidagi chiziqli bog''liqlikni topish.

Formula: y = wx + b. Bu yerda w og''irlik (slope), b bias (intercept). Ma''lumotlar asosida w va b qiymatlarini topishimiz kerak. Bu uchun yo''qotish funksiyasini (loss function) minimallashtiramiz.

Eng ko''p ishlatiladigan loss — Mean Squared Error: barcha xatolarning kvadratlari o''rtachasi. Gradient descent algoritmi bilan loss ni kamaytiramiz, har qadamda w va b ni biroz o''zgartiramiz.

scikit-learn kutubxonasi bilan amalga oshirish juda oson: from sklearn.linear_model import LinearRegression, model = LinearRegression(), model.fit(X, y). Lekin asosini tushunish muhim — boshqa algoritmlar shu printsipga asoslangan.', '2026-06-05 09:51:00');
