INSERT INTO evaluations (lesson_id, overall_score, topic_score, speech_score, method_score, interaction_score, feedback_score, summary, strengths, improvements, advice, created_at) VALUES (1021, 54, 9, 14, 10, 9, 12, 'Dars sxematik o''tdi — o''quvchilar bilan muloqot deyarli yo''q edi.', '["Mavzu aniq va izchil yoritildi.","Misollar amaliy va o''quvchilarga tushunarli.","O''qituvchi savollarga aniq javob berdi."]', '["O''quvchilarga savollar berib qatnashtirish keng bo''lishi kerak.","Ko''proq amaliy mashqlar berilsa yaxshi bo''lardi.","Dars oxirida qisqa xulosa va kalit fikrlarni qaytarish."]', '["Muhim atamalarni taxtaga yozib qo''yish — eslab qolishni osonlashtiradi.","Uy vazifasi sifatida 2-3 ta savol berish va keyingi darsda ko''rib chiqish.","Eng oddiy misoldan boshlab keyingi qadamga o''tish — barcha o''quvchilar bilan bir tezlikda yurishga yordam beradi."]', '2026-06-23 12:38:00');
INSERT INTO lessons (id, user_id, group_name, topic, course_type, duration_seconds, transcript, created_at) VALUES (1022, 1000, 'DI-201', 'DA — Loyiha taqdimoti', 'Dasturlash asoslari', 2702, 'Salom o''quvchilar. Bugungi darsimizda biz o''zgaruvchilar va ularning turlari haqida gaplashamiz. O''zgaruvchi — bu ma''lumotni saqlash uchun nomli xotira maydoni. Python tilida o''zgaruvchini e''lon qilish uchun ismni yozib, teng belgisidan keyin qiymatni kiritamiz.

Misol uchun: yosh = 20. Bu yerda yosh degan o''zgaruvchiga 20 qiymati berildi. Endi keling turlarga e''tibor beraylik. Asosan to''rtta turdagi ma''lumot bor: int — butun sonlar, float — kasr sonlar, str — matn, va bool — rost yoki yolg''on qiymatlar.

Type funksiyasi orqali o''zgaruvchining turini bilib olishimiz mumkin. Print(type(yosh)) deb yozsak, ekranda class int chiqadi. Bu Python avtomatik ravishda turini aniqlaganini ko''rsatadi.

Endi sizga vazifa: o''z ismingiz va yoshingizni ifodalaydigan ikki o''zgaruvchi yarating va ekranga chiqaring. Keyingi darsda biz shartli operatorlarni o''rganamiz.', '2026-06-06 12:24:00');
INSERT INTO evaluations (lesson_id, overall_score, topic_score, speech_score, method_score, interaction_score, feedback_score, summary, strengths, improvements, advice, created_at) VALUES (1022, 51, 13, 10, 10, 10, 8, 'Mavzu yetarlicha chuqur ochilmadi. Misollar va amaliy mashqlar yetishmadi.', '["Ovoz baland va aniq, jaranglashi yaxshi.","Mavzu aniq va izchil yoritildi."]', '["Murakkab atamalar uchun qisqacha takror berib turish foydali.","Yozma misollarni daftar yoki taxta orqali ko''rsatish."]', '["Darsda Q&A vaqti aniq belgilash — talabalar savol berishdan tortinmasin.","Uy vazifasi sifatida 2-3 ta savol berish va keyingi darsda ko''rib chiqish.","Tinglovchilarga 5-7 daqiqada bir savol berish — diqqatni saqlaydi."]', '2026-06-06 12:24:00');
INSERT INTO lessons (id, user_id, group_name, topic, course_type, duration_seconds, transcript, created_at) VALUES (1023, 1000, 'DI-201', 'DA — Yangi mavzu kirishi', 'Dasturlash asoslari', 1303, 'Bugun shartli operatorlar mavzusiga to''xtalamiz. Dastur har doim chiziqli bajarilmaydi — ba''zan biz uning yo''nalishini boshqarishimiz kerak. Buning uchun if konstruksiyasidan foydalanamiz.

Sintaksisi juda oddiy: if shart, keyin ikki nuqta, va keyingi qatorda tabulyatsiya bilan bajariladigan kod. Misol: if yosh >= 18: print("Voyaga yetgan"). Agar shart bajarilmasa, else bloki ishlaydi.

Bir nechta shartlarni tekshirish uchun elif kalit so''zi bor. Masalan: if score >= 90 print("a''lo"), elif score >= 70 print("yaxshi"), else print("qoniqarli"). Ushbu konstruksiya darslar bahosini aniqlash uchun ko''p ishlatiladi.

Operator and, or, not yordamida murakkab shartlar tuzish mumkin. Eslatib o''taman: Python da indentatsiya juda muhim — agar bo''shliqlar to''g''ri qo''yilmasa, dastur xato beradi.', '2026-06-06 09:27:00');
INSERT INTO evaluations (lesson_id, overall_score, topic_score, speech_score, method_score, interaction_score, feedback_score, summary, strengths, improvements, advice, created_at) VALUES (1023, 65, 12, 14, 12, 15, 12, 'O''rtacha sifatdagi dars — mavzu qamrab olindi, lekin o''quvchilar reaktsiyasiga ko''p e''tibor berilmadi.', '["Mavzu aniq va izchil yoritildi.","O''quvchilar bilan o''zaro muloqot yaxshi tashkil etilgan."]', '["Dars oxirida qisqa xulosa va kalit fikrlarni qaytarish.","Murakkab atamalar uchun qisqacha takror berib turish foydali."]', '["Darsda Q&A vaqti aniq belgilash — talabalar savol berishdan tortinmasin.","Har dars boshida 1-2 daqiqa o''tgan darsni qaytarish — yaxshi natija beradi."]', '2026-06-06 09:27:00');
