INSERT INTO evaluations (lesson_id, overall_score, topic_score, speech_score, method_score, interaction_score, feedback_score, summary, strengths, improvements, advice, created_at) VALUES (1024, 70, 14, 15, 13, 14, 14, 'Dars umumiy ma''noda yaxshi olib borildi, lekin amaliy qism va o''quvchilarni jalb qilish kuchaytirilishi kerak.', '["Tushunchalar bosqichma-bosqich oddiydan murakkabga qarab tushuntirildi.","Misollar amaliy va o''quvchilarga tushunarli.","O''qituvchi savollarga aniq javob berdi."]', '["Tezlikni biroz pasaytirish — ayrim joylar tez o''tib ketdi.","Yozma misollarni daftar yoki taxta orqali ko''rsatish.","Dars oxirida qisqa xulosa va kalit fikrlarni qaytarish."]', '["Tinglovchilarga 5-7 daqiqada bir savol berish — diqqatni saqlaydi.","Uy vazifasi sifatida 2-3 ta savol berish va keyingi darsda ko''rib chiqish.","Darsda Q&A vaqti aniq belgilash — talabalar savol berishdan tortinmasin."]', '2026-05-28 11:45:00');
INSERT INTO lessons (id, user_id, group_name, topic, course_type, duration_seconds, transcript, created_at) VALUES (1025, 1000, 'DI-201', 'DA — Loyiha taqdimoti', 'Dasturlash asoslari', 4236, 'Bugun shartli operatorlar mavzusiga to''xtalamiz. Dastur har doim chiziqli bajarilmaydi — ba''zan biz uning yo''nalishini boshqarishimiz kerak. Buning uchun if konstruksiyasidan foydalanamiz.

Sintaksisi juda oddiy: if shart, keyin ikki nuqta, va keyingi qatorda tabulyatsiya bilan bajariladigan kod. Misol: if yosh >= 18: print("Voyaga yetgan"). Agar shart bajarilmasa, else bloki ishlaydi.

Bir nechta shartlarni tekshirish uchun elif kalit so''zi bor. Masalan: if score >= 90 print("a''lo"), elif score >= 70 print("yaxshi"), else print("qoniqarli"). Ushbu konstruksiya darslar bahosini aniqlash uchun ko''p ishlatiladi.

Operator and, or, not yordamida murakkab shartlar tuzish mumkin. Eslatib o''taman: Python da indentatsiya juda muhim — agar bo''shliqlar to''g''ri qo''yilmasa, dastur xato beradi.', '2026-06-03 09:30:00');
INSERT INTO evaluations (lesson_id, overall_score, topic_score, speech_score, method_score, interaction_score, feedback_score, summary, strengths, improvements, advice, created_at) VALUES (1025, 85, 19, 18, 16, 17, 15, 'Pedagogik jihatdan kuchli dars. Kichik takomillashtirishlar bilan a''lo bo''lishi mumkin.', '["O''quvchilar bilan o''zaro muloqot yaxshi tashkil etilgan.","O''qituvchi savollarga aniq javob berdi.","Tushunchalar bosqichma-bosqich oddiydan murakkabga qarab tushuntirildi."]', '["Dars oxirida qisqa xulosa va kalit fikrlarni qaytarish.","Ko''proq amaliy mashqlar berilsa yaxshi bo''lardi.","O''quvchilarga savollar berib qatnashtirish keng bo''lishi kerak."]', '["Har dars boshida 1-2 daqiqa o''tgan darsni qaytarish — yaxshi natija beradi.","Muhim atamalarni taxtaga yozib qo''yish — eslab qolishni osonlashtiradi.","Uy vazifasi sifatida 2-3 ta savol berish va keyingi darsda ko''rib chiqish."]', '2026-06-03 09:30:00');
