INSERT INTO evaluations (lesson_id, overall_score, topic_score, speech_score, method_score, interaction_score, feedback_score, summary, strengths, improvements, advice, created_at) VALUES (1026, 81, 17, 19, 16, 16, 13, 'Mazmun va shaklning yaxshi muvozanati. Misollar mavzuni qo''llab-quvvatlaydi.', '["Misollar amaliy va o''quvchilarga tushunarli.","O''quvchilar bilan o''zaro muloqot yaxshi tashkil etilgan."]', '["Dars oxirida qisqa xulosa va kalit fikrlarni qaytarish.","Murakkab atamalar uchun qisqacha takror berib turish foydali.","Ko''proq amaliy mashqlar berilsa yaxshi bo''lardi."]', '["Uy vazifasi sifatida 2-3 ta savol berish va keyingi darsda ko''rib chiqish.","Darsda Q&A vaqti aniq belgilash — talabalar savol berishdan tortinmasin.","Har dars boshida 1-2 daqiqa o''tgan darsni qaytarish — yaxshi natija beradi."]', '2026-06-08 15:53:00');
