INSERT INTO evaluations (lesson_id, overall_score, topic_score, speech_score, method_score, interaction_score, feedback_score, summary, strengths, improvements, advice, created_at) VALUES (1027, 61, 12, 14, 15, 10, 10, 'Asosiy mavzu yetkazildi, lekin tushuntirishda ba''zi joylar tezroq o''tib ketdi.', '["Real hayotdagi misollar yordamida nazariya mustahkamlandi.","Tushunchalar bosqichma-bosqich oddiydan murakkabga qarab tushuntirildi."]', '["Ko''proq amaliy mashqlar berilsa yaxshi bo''lardi.","O''quvchilarga savollar berib qatnashtirish keng bo''lishi kerak."]', '["Muhim atamalarni taxtaga yozib qo''yish — eslab qolishni osonlashtiradi.","Har dars boshida 1-2 daqiqa o''tgan darsni qaytarish — yaxshi natija beradi.","Real loyiha yoki amaliy vazifa qo''shish — motivatsiyani oshiradi."]', '2026-06-27 17:21:00');
INSERT INTO lessons (id, user_id, group_name, topic, course_type, duration_seconds, transcript, created_at) VALUES (1028, 1005, 'DI-201', 'MO — Asosiy tushunchalar', 'Mashinaviy o''rganish', 3151, 'Linear regressiya — eng oddiy va eng asosiy ML algoritm. Maqsadi: kirish (X) va chiqish (y) o''rtasidagi chiziqli bog''liqlikni topish.

Formula: y = wx + b. Bu yerda w og''irlik (slope), b bias (intercept). Ma''lumotlar asosida w va b qiymatlarini topishimiz kerak. Bu uchun yo''qotish funksiyasini (loss function) minimallashtiramiz.

Eng ko''p ishlatiladigan loss — Mean Squared Error: barcha xatolarning kvadratlari o''rtachasi. Gradient descent algoritmi bilan loss ni kamaytiramiz, har qadamda w va b ni biroz o''zgartiramiz.

scikit-learn kutubxonasi bilan amalga oshirish juda oson: from sklearn.linear_model import LinearRegression, model = LinearRegression(), model.fit(X, y). Lekin asosini tushunish muhim — boshqa algoritmlar shu printsipga asoslangan.', '2026-06-27 11:03:00');
