INSERT INTO evaluations (lesson_id, overall_score, topic_score, speech_score, method_score, interaction_score, feedback_score, summary, strengths, improvements, advice, created_at) VALUES (1031, 58, 14, 13, 11, 11, 9, 'Tushuntirish nomuvofiq, ba''zi muhim joylar o''tkazib yuborildi.', '["Misollar amaliy va o''quvchilarga tushunarli.","Tushunchalar bosqichma-bosqich oddiydan murakkabga qarab tushuntirildi.","Vizual yoki yozma misollar kontsentratsiyaga yordam berdi."]', '["Dars oxirida qisqa xulosa va kalit fikrlarni qaytarish.","Ko''proq amaliy mashqlar berilsa yaxshi bo''lardi.","Yozma misollarni daftar yoki taxta orqali ko''rsatish."]', '["Har dars boshida 1-2 daqiqa o''tgan darsni qaytarish — yaxshi natija beradi.","Eng oddiy misoldan boshlab keyingi qadamga o''tish — barcha o''quvchilar bilan bir tezlikda yurishga yordam beradi."]', '2026-07-18 16:59:00');
INSERT INTO lessons (id, user_id, group_name, topic, course_type, duration_seconds, transcript, created_at) VALUES (1032, 1000, 'DI-202', 'DA — Yangi mavzu kirishi', 'Dasturlash asoslari', 2554, 'Funksiyalar — bu kodni qayta ishlatish uchun asosiy vosita. def kalit so''zi bilan funksiyani aniqlaymiz. Argumentlar qavslar ichida, return orqali qiymat qaytariladi.

Misol uchun, ikki sonni qo''shadigan funksiya: def yigindi(a, b): return a + b. Endi bu funksiyani istalgan joyda chaqirsak bo''ladi: natija = yigindi(5, 3). Bu yerda 8 qaytariladi.

Default argumentlar ham mavjud. Agar argument berilmasa, default qiymat ishlatiladi. Misol: def salom(ism="dunyo"): print("Salom", ism). Salom() chaqirilganda "Salom dunyo" chiqadi.

Funksiya nomlari mazmunli bo''lishi kerak. yigindi, ko_paytma, foiz_hisobla — bularning hammasi yaxshi nomlar. f1, x, abc — yomon nomlar. Yaxshi kod yozish — bu o''qilishi oson kod yozish.', '2026-06-25 13:07:00');
