INSERT INTO lessons (id, user_id, group_name, topic, course_type, duration_seconds, transcript, created_at) VALUES (1034, 1000, 'DI-202', 'DA — Takrorlash va xulosa', 'Dasturlash asoslari', 3447, 'Salom o''quvchilar. Bugungi darsimizda biz o''zgaruvchilar va ularning turlari haqida gaplashamiz. O''zgaruvchi — bu ma''lumotni saqlash uchun nomli xotira maydoni. Python tilida o''zgaruvchini e''lon qilish uchun ismni yozib, teng belgisidan keyin qiymatni kiritamiz.

Misol uchun: yosh = 20. Bu yerda yosh degan o''zgaruvchiga 20 qiymati berildi. Endi keling turlarga e''tibor beraylik. Asosan to''rtta turdagi ma''lumot bor: int — butun sonlar, float — kasr sonlar, str — matn, va bool — rost yoki yolg''on qiymatlar.

Type funksiyasi orqali o''zgaruvchining turini bilib olishimiz mumkin. Print(type(yosh)) deb yozsak, ekranda class int chiqadi. Bu Python avtomatik ravishda turini aniqlaganini ko''rsatadi.

Endi sizga vazifa: o''z ismingiz va yoshingizni ifodalaydigan ikki o''zgaruvchi yarating va ekranga chiqaring. Keyingi darsda biz shartli operatorlarni o''rganamiz.', '2026-06-07 16:29:00');
