INSERT INTO evaluations (lesson_id, overall_score, topic_score, speech_score, method_score, interaction_score, feedback_score, summary, strengths, improvements, advice, created_at) VALUES (1035, 59, 12, 11, 15, 9, 12, 'Dars sxematik o''tdi — o''quvchilar bilan muloqot deyarli yo''q edi.', '["Ovoz baland va aniq, jaranglashi yaxshi.","O''quvchilar bilan o''zaro muloqot yaxshi tashkil etilgan."]', '["Ko''proq amaliy mashqlar berilsa yaxshi bo''lardi.","Dars oxirida qisqa xulosa va kalit fikrlarni qaytarish."]', '["Tinglovchilarga 5-7 daqiqada bir savol berish — diqqatni saqlaydi.","Darsda Q&A vaqti aniq belgilash — talabalar savol berishdan tortinmasin.","Uy vazifasi sifatida 2-3 ta savol berish va keyingi darsda ko''rib chiqish."]', '2026-06-23 13:48:00');
INSERT INTO lessons (id, user_id, group_name, topic, course_type, duration_seconds, transcript, created_at) VALUES (1036, 1000, 'DI-202', 'DA — Misollar va tahlil', 'Dasturlash asoslari', 2245, 'Funksiyalar — bu kodni qayta ishlatish uchun asosiy vosita. def kalit so''zi bilan funksiyani aniqlaymiz. Argumentlar qavslar ichida, return orqali qiymat qaytariladi.

Misol uchun, ikki sonni qo''shadigan funksiya: def yigindi(a, b): return a + b. Endi bu funksiyani istalgan joyda chaqirsak bo''ladi: natija = yigindi(5, 3). Bu yerda 8 qaytariladi.

Default argumentlar ham mavjud. Agar argument berilmasa, default qiymat ishlatiladi. Misol: def salom(ism="dunyo"): print("Salom", ism). Salom() chaqirilganda "Salom dunyo" chiqadi.

Funksiya nomlari mazmunli bo''lishi kerak. yigindi, ko_paytma, foiz_hisobla — bularning hammasi yaxshi nomlar. f1, x, abc — yomon nomlar. Yaxshi kod yozish — bu o''qilishi oson kod yozish.', '2026-06-25 08:45:00');
INSERT INTO evaluations (lesson_id, overall_score, topic_score, speech_score, method_score, interaction_score, feedback_score, summary, strengths, improvements, advice, created_at) VALUES (1036, 54, 11, 9, 13, 10, 11, 'Dars sxematik o''tdi — o''quvchilar bilan muloqot deyarli yo''q edi.', '["Real hayotdagi misollar yordamida nazariya mustahkamlandi.","Vizual yoki yozma misollar kontsentratsiyaga yordam berdi."]', '["Tushuntirish boshlanishida darsning maqsadi aniq aytilishi kerak.","O''quvchilarga savollar berib qatnashtirish keng bo''lishi kerak.","Dars oxirida qisqa xulosa va kalit fikrlarni qaytarish."]', '["Real loyiha yoki amaliy vazifa qo''shish — motivatsiyani oshiradi.","Muhim atamalarni taxtaga yozib qo''yish — eslab qolishni osonlashtiradi.","Har dars boshida 1-2 daqiqa o''tgan darsni qaytarish — yaxshi natija beradi."]', '2026-06-25 08:45:00');
INSERT INTO lessons (id, user_id, group_name, topic, course_type, duration_seconds, transcript, created_at) VALUES (1037, 1000, 'DI-202', 'DA — Test va o''zlashtirish', 'Dasturlash asoslari', 4428, 'Salom o''quvchilar. Bugungi darsimizda biz o''zgaruvchilar va ularning turlari haqida gaplashamiz. O''zgaruvchi — bu ma''lumotni saqlash uchun nomli xotira maydoni. Python tilida o''zgaruvchini e''lon qilish uchun ismni yozib, teng belgisidan keyin qiymatni kiritamiz.

Misol uchun: yosh = 20. Bu yerda yosh degan o''zgaruvchiga 20 qiymati berildi. Endi keling turlarga e''tibor beraylik. Asosan to''rtta turdagi ma''lumot bor: int — butun sonlar, float — kasr sonlar, str — matn, va bool — rost yoki yolg''on qiymatlar.

Type funksiyasi orqali o''zgaruvchining turini bilib olishimiz mumkin. Print(type(yosh)) deb yozsak, ekranda class int chiqadi. Bu Python avtomatik ravishda turini aniqlaganini ko''rsatadi.

Endi sizga vazifa: o''z ismingiz va yoshingizni ifodalaydigan ikki o''zgaruvchi yarating va ekranga chiqaring. Keyingi darsda biz shartli operatorlarni o''rganamiz.', '2026-06-13 09:29:00');
INSERT INTO evaluations (lesson_id, overall_score, topic_score, speech_score, method_score, interaction_score, feedback_score, summary, strengths, improvements, advice, created_at) VALUES (1037, 65, 13, 12, 15, 10, 15, 'Asosiy mavzu yetkazildi, lekin tushuntirishda ba''zi joylar tezroq o''tib ketdi.', '["Real hayotdagi misollar yordamida nazariya mustahkamlandi.","Mavzu aniq va izchil yoritildi.","Vizual yoki yozma misollar kontsentratsiyaga yordam berdi."]', '["Murakkab atamalar uchun qisqacha takror berib turish foydali.","Yozma misollarni daftar yoki taxta orqali ko''rsatish."]', '["Real loyiha yoki amaliy vazifa qo''shish — motivatsiyani oshiradi.","Darsda Q&A vaqti aniq belgilash — talabalar savol berishdan tortinmasin."]', '2026-06-13 09:29:00');
INSERT INTO lessons (id, user_id, group_name, topic, course_type, duration_seconds, transcript, created_at) VALUES (1038, 1005, 'DI-202', 'MO — Test va o''zlashtirish', 'Mashinaviy o''rganish', 4265, 'Linear regressiya — eng oddiy va eng asosiy ML algoritm. Maqsadi: kirish (X) va chiqish (y) o''rtasidagi chiziqli bog''liqlikni topish.

Formula: y = wx + b. Bu yerda w og''irlik (slope), b bias (intercept). Ma''lumotlar asosida w va b qiymatlarini topishimiz kerak. Bu uchun yo''qotish funksiyasini (loss function) minimallashtiramiz.

Eng ko''p ishlatiladigan loss — Mean Squared Error: barcha xatolarning kvadratlari o''rtachasi. Gradient descent algoritmi bilan loss ni kamaytiramiz, har qadamda w va b ni biroz o''zgartiramiz.

scikit-learn kutubxonasi bilan amalga oshirish juda oson: from sklearn.linear_model import LinearRegression, model = LinearRegression(), model.fit(X, y). Lekin asosini tushunish muhim — boshqa algoritmlar shu printsipga asoslangan.', '2026-05-25 08:13:00');
INSERT INTO evaluations (lesson_id, overall_score, topic_score, speech_score, method_score, interaction_score, feedback_score, summary, strengths, improvements, advice, created_at) VALUES (1038, 59, 11, 11, 13, 13, 11, 'Mavzu yetarlicha chuqur ochilmadi. Misollar va amaliy mashqlar yetishmadi.', '["Mavzu aniq va izchil yoritildi.","O''qituvchi savollarga aniq javob berdi."]', '["Tezlikni biroz pasaytirish — ayrim joylar tez o''tib ketdi.","Dars oxirida qisqa xulosa va kalit fikrlarni qaytarish.","Tushuntirish boshlanishida darsning maqsadi aniq aytilishi kerak."]', '["Uy vazifasi sifatida 2-3 ta savol berish va keyingi darsda ko''rib chiqish.","Real loyiha yoki amaliy vazifa qo''shish — motivatsiyani oshiradi."]', '2026-05-25 08:13:00');
