INSERT INTO evaluations (lesson_id, overall_score, topic_score, speech_score, method_score, interaction_score, feedback_score, summary, strengths, improvements, advice, created_at) VALUES (1044, 82, 17, 17, 20, 14, 14, 'Mazmun va shaklning yaxshi muvozanati. Misollar mavzuni qo''llab-quvvatlaydi.', '["O''qituvchi savollarga aniq javob berdi.","Tushunchalar bosqichma-bosqich oddiydan murakkabga qarab tushuntirildi."]', '["Tezlikni biroz pasaytirish — ayrim joylar tez o''tib ketdi.","Ko''proq amaliy mashqlar berilsa yaxshi bo''lardi.","O''quvchilarga savollar berib qatnashtirish keng bo''lishi kerak."]', '["Har dars boshida 1-2 daqiqa o''tgan darsni qaytarish — yaxshi natija beradi.","Uy vazifasi sifatida 2-3 ta savol berish va keyingi darsda ko''rib chiqish.","Tinglovchilarga 5-7 daqiqada bir savol berish — diqqatni saqlaydi."]', '2026-05-28 08:00:00');
INSERT INTO lessons (id, user_id, group_name, topic, course_type, duration_seconds, transcript, created_at) VALUES (1045, 1007, 'DI-301', 'DM — Loyiha taqdimoti', 'Diskret matematika', 1188, 'Bugungi mavzu — to''plamlar va ulardagi amallar. To''plam — bu aniq belgilangan obyektlar yig''indisi. A = {1, 2, 3} kabi yoziladi. Element to''plamga tegishli yoki tegishli emas.

Asosiy amallar: birlashma (A∪B) — barcha elementlar; kesishma (A∩B) — umumiy elementlar; ayirma (A\B) — A da bor lekin B da yo''q; to''ldiruvchi — universal to''plamdagi qolganlar.

Kuchli to''plam (power set) — berilgan to''plamning barcha qism to''plamlari to''plami. Agar A = {a, b} bo''lsa, P(A) = {∅, {a}, {b}, {a,b}}. Ya''ni 2^n ta element bo''ladi.

Vennin diagrammasi to''plam munosabatlarini vizualizatsiya qilish uchun ajoyib vosita. Ikki yoki uchta to''plam uchun yaxshi ishlaydi. Mantiqiy fikrlashda ham qo''l keladi: "barcha A — B" degani A ⊆ B.', '2026-05-25 16:39:00');
INSERT INTO evaluations (lesson_id, overall_score, topic_score, speech_score, method_score, interaction_score, feedback_score, summary, strengths, improvements, advice, created_at) VALUES (1045, 80, 18, 18, 17, 13, 14, 'Dars yaxshi tashkil etilgan, mavzu chuqur va aniq yoritilgan. O''quvchilar bilan muloqot mustahkam.', '["O''quvchilar bilan o''zaro muloqot yaxshi tashkil etilgan.","Mavzu aniq va izchil yoritildi.","Tushunchalar bosqichma-bosqich oddiydan murakkabga qarab tushuntirildi."]', '["Tushuntirish boshlanishida darsning maqsadi aniq aytilishi kerak.","Ko''proq amaliy mashqlar berilsa yaxshi bo''lardi.","Tezlikni biroz pasaytirish — ayrim joylar tez o''tib ketdi."]', '["Har dars boshida 1-2 daqiqa o''tgan darsni qaytarish — yaxshi natija beradi.","Tinglovchilarga 5-7 daqiqada bir savol berish — diqqatni saqlaydi.","Muhim atamalarni taxtaga yozib qo''yish — eslab qolishni osonlashtiradi."]', '2026-05-25 16:39:00');
