INSERT INTO evaluations (lesson_id, overall_score, topic_score, speech_score, method_score, interaction_score, feedback_score, summary, strengths, improvements, advice, created_at) VALUES (1046, 62, 10, 15, 12, 15, 10, 'Asosiy mavzu yetkazildi, lekin tushuntirishda ba''zi joylar tezroq o''tib ketdi.', '["Vizual yoki yozma misollar kontsentratsiyaga yordam berdi.","O''qituvchi savollarga aniq javob berdi.","O''quvchilar bilan o''zaro muloqot yaxshi tashkil etilgan."]', '["Tezlikni biroz pasaytirish — ayrim joylar tez o''tib ketdi.","O''quvchilarga savollar berib qatnashtirish keng bo''lishi kerak."]', '["Real loyiha yoki amaliy vazifa qo''shish — motivatsiyani oshiradi.","Muhim atamalarni taxtaga yozib qo''yish — eslab qolishni osonlashtiradi.","Darsda Q&A vaqti aniq belgilash — talabalar savol berishdan tortinmasin."]', '2026-07-12 09:43:00');
INSERT INTO lessons (id, user_id, group_name, topic, course_type, duration_seconds, transcript, created_at) VALUES (1047, 1007, 'DI-301', 'DM — Test va o''zlashtirish', 'Diskret matematika', 2793, 'Bugungi mavzu — to''plamlar va ulardagi amallar. To''plam — bu aniq belgilangan obyektlar yig''indisi. A = {1, 2, 3} kabi yoziladi. Element to''plamga tegishli yoki tegishli emas.

