INSERT INTO evaluations (lesson_id, overall_score, topic_score, speech_score, method_score, interaction_score, feedback_score, summary, strengths, improvements, advice, created_at) VALUES (1047, 74, 14, 16, 15, 16, 13, 'Dars umumiy ma''noda yaxshi olib borildi, lekin amaliy qism va o''quvchilarni jalb qilish kuchaytirilishi kerak.', '["Ovoz baland va aniq, jaranglashi yaxshi.","Mavzu aniq va izchil yoritildi."]', '["Tezlikni biroz pasaytirish — ayrim joylar tez o''tib ketdi.","Yozma misollarni daftar yoki taxta orqali ko''rsatish.","O''quvchilarga savollar berib qatnashtirish keng bo''lishi kerak."]', '["Uy vazifasi sifatida 2-3 ta savol berish va keyingi darsda ko''rib chiqish.","Muhim atamalarni taxtaga yozib qo''yish — eslab qolishni osonlashtiradi.","Har dars boshida 1-2 daqiqa o''tgan darsni qaytarish — yaxshi natija beradi."]', '2026-06-06 08:00:00');
