INSERT INTO evaluations (lesson_id, overall_score, topic_score, speech_score, method_score, interaction_score, feedback_score, summary, strengths, improvements, advice, created_at) VALUES (1050, 84, 17, 17, 18, 15, 17, 'Pedagogik jihatdan kuchli dars. Kichik takomillashtirishlar bilan a''lo bo''lishi mumkin.', '["O''qituvchi savollarga aniq javob berdi.","Real hayotdagi misollar yordamida nazariya mustahkamlandi.","Vizual yoki yozma misollar kontsentratsiyaga yordam berdi."]', '["Tushuntirish boshlanishida darsning maqsadi aniq aytilishi kerak.","Tezlikni biroz pasaytirish — ayrim joylar tez o''tib ketdi.","Yozma misollarni daftar yoki taxta orqali ko''rsatish."]', '["Uy vazifasi sifatida 2-3 ta savol berish va keyingi darsda ko''rib chiqish.","Darsda Q&A vaqti aniq belgilash — talabalar savol berishdan tortinmasin."]', '2026-06-03 17:52:00');
