INSERT INTO evaluations (lesson_id, overall_score, topic_score, speech_score, method_score, interaction_score, feedback_score, summary, strengths, improvements, advice, created_at) VALUES (1051, 55, 11, 10, 13, 10, 11, 'Tushuntirish nomuvofiq, ba''zi muhim joylar o''tkazib yuborildi.', '["Vizual yoki yozma misollar kontsentratsiyaga yordam berdi.","Tushunchalar bosqichma-bosqich oddiydan murakkabga qarab tushuntirildi.","Mavzu aniq va izchil yoritildi."]', '["Ko''proq amaliy mashqlar berilsa yaxshi bo''lardi.","Yozma misollarni daftar yoki taxta orqali ko''rsatish.","Dars oxirida qisqa xulosa va kalit fikrlarni qaytarish."]', '["Darsda Q&A vaqti aniq belgilash — talabalar savol berishdan tortinmasin.","Real loyiha yoki amaliy vazifa qo''shish — motivatsiyani oshiradi."]', '2026-06-08 10:18:00');
INSERT INTO lessons (id, user_id, group_name, topic, course_type, duration_seconds, transcript, created_at) VALUES (1052, 1002, 'DI-301', 'VD — Loyiha taqdimoti', 'Veb dasturlash', 1380, 'React komponentlari haqida gaplashamiz. Komponent — bu UI ning qayta ishlatiladigan qismi. Function komponent eng zamonaviy yondashuv hisoblanadi.

Props orqali komponentga ma''lumot uzatamiz: function Welcome(props) return Salom props.ism. State esa komponentning ichki holati. useState hook orqali boshqarsamiz: const [son setSon] = useState(0).

Komponentlar bir-biriga joylashishi mumkin. Bu kompozitsiya prinsipi. Asosiy ilova App komponenti bo''lib, uning ichida Header, Main, Footer komponentlari bo''lishi mumkin. Har bir komponent o''z mas''uliyatiga ega.

useEffect hook side effect lar uchun ishlatiladi: API chaqiruvi, eventListener qo''shish, timer. Dependency array orqali qachon ishga tushishini boshqarsamiz. Bo''sh massiv [] berilsa, faqat bir marta — komponent yuklanganda ishlaydi.', '2026-06-03 11:27:00');
INSERT INTO evaluations (lesson_id, overall_score, topic_score, speech_score, method_score, interaction_score, feedback_score, summary, strengths, improvements, advice, created_at) VALUES (1052, 64, 15, 12, 16, 11, 10, 'Asosiy mavzu yetkazildi, lekin tushuntirishda ba''zi joylar tezroq o''tib ketdi.', '["Real hayotdagi misollar yordamida nazariya mustahkamlandi.","Tushunchalar bosqichma-bosqich oddiydan murakkabga qarab tushuntirildi.","Mavzu aniq va izchil yoritildi."]', '["Ko''proq amaliy mashqlar berilsa yaxshi bo''lardi.","O''quvchilarga savollar berib qatnashtirish keng bo''lishi kerak."]', '["Tinglovchilarga 5-7 daqiqada bir savol berish — diqqatni saqlaydi.","Darsda Q&A vaqti aniq belgilash — talabalar savol berishdan tortinmasin."]', '2026-06-03 11:27:00');
INSERT INTO lessons (id, user_id, group_name, topic, course_type, duration_seconds, transcript, created_at) VALUES (1053, 1002, 'DI-301', 'VD — Misollar va tahlil', 'Veb dasturlash', 2407, 'Bugun biz HTTP protokolining asoslarini ko''rib chiqamiz. HTTP — bu mijoz va server o''rtasidagi muloqot tili. Brauzer so''rov yuboradi, server javob beradi.

So''rovning uchta asosiy qismi bor: metod, URL, va headerlar. Eng ko''p ishlatiladigan metodlar: GET — ma''lumot olish, POST — yangi ma''lumot yuborish, PUT — yangilash, DELETE — o''chirish. Bularning to''plami RESTful API ning asosini tashkil qiladi.

Status kodlar javobning natijasini bildiradi. 200 — muvaffaqiyat, 201 — yaratildi, 404 — topilmadi, 401 — autentifikatsiya kerak, 500 — server xatosi. Yaxshi API har doim to''g''ri status kod qaytarishi shart.

Bugun amaliy mashq sifatida fetch funksiyasi orqali oddiy API''dan ma''lumot olib, sahifada ko''rsatamiz. JSON formati zamonaviy veb da standart hisoblanadi.', '2026-06-15 09:51:00');
INSERT INTO evaluations (lesson_id, overall_score, topic_score, speech_score, method_score, interaction_score, feedback_score, summary, strengths, improvements, advice, created_at) VALUES (1053, 84, 18, 16, 19, 14, 17, 'Mazmun va shaklning yaxshi muvozanati. Misollar mavzuni qo''llab-quvvatlaydi.', '["Misollar amaliy va o''quvchilarga tushunarli.","Ovoz baland va aniq, jaranglashi yaxshi.","Real hayotdagi misollar yordamida nazariya mustahkamlandi."]', '["Ko''proq amaliy mashqlar berilsa yaxshi bo''lardi.","Yozma misollarni daftar yoki taxta orqali ko''rsatish.","Dars oxirida qisqa xulosa va kalit fikrlarni qaytarish."]', '["Har dars boshida 1-2 daqiqa o''tgan darsni qaytarish — yaxshi natija beradi.","Eng oddiy misoldan boshlab keyingi qadamga o''tish — barcha o''quvchilar bilan bir tezlikda yurishga yordam beradi.","Uy vazifasi sifatida 2-3 ta savol berish va keyingi darsda ko''rib chiqish."]', '2026-06-15 09:51:00');
INSERT INTO lessons (id, user_id, group_name, topic, course_type, duration_seconds, transcript, created_at) VALUES (1054, 1002, 'DI-301', 'VD — Asosiy tushunchalar', 'Veb dasturlash', 4092, 'React komponentlari haqida gaplashamiz. Komponent — bu UI ning qayta ishlatiladigan qismi. Function komponent eng zamonaviy yondashuv hisoblanadi.

