INSERT INTO evaluations (lesson_id, overall_score, topic_score, speech_score, method_score, interaction_score, feedback_score, summary, strengths, improvements, advice, created_at) VALUES (1068, 61, 15, 10, 12, 14, 10, 'O''rtacha sifatdagi dars — mavzu qamrab olindi, lekin o''quvchilar reaktsiyasiga ko''p e''tibor berilmadi.', '["O''quvchilar bilan o''zaro muloqot yaxshi tashkil etilgan.","Mavzu aniq va izchil yoritildi.","Real hayotdagi misollar yordamida nazariya mustahkamlandi."]', '["Dars oxirida qisqa xulosa va kalit fikrlarni qaytarish.","Yozma misollarni daftar yoki taxta orqali ko''rsatish.","Tushuntirish boshlanishida darsning maqsadi aniq aytilishi kerak."]', '["Eng oddiy misoldan boshlab keyingi qadamga o''tish — barcha o''quvchilar bilan bir tezlikda yurishga yordam beradi.","Darsda Q&A vaqti aniq belgilash — talabalar savol berishdan tortinmasin."]', '2026-07-10 11:16:00');
