INSERT INTO evaluations (lesson_id, overall_score, topic_score, speech_score, method_score, interaction_score, feedback_score, summary, strengths, improvements, advice, created_at) VALUES (1070, 62, 10, 12, 15, 12, 13, 'Dars umumiy ma''noda yaxshi olib borildi, lekin amaliy qism va o''quvchilarni jalb qilish kuchaytirilishi kerak.', '["Ovoz baland va aniq, jaranglashi yaxshi.","O''quvchilar bilan o''zaro muloqot yaxshi tashkil etilgan.","Mavzu aniq va izchil yoritildi."]', '["Ko''proq amaliy mashqlar berilsa yaxshi bo''lardi.","Tezlikni biroz pasaytirish — ayrim joylar tez o''tib ketdi.","Murakkab atamalar uchun qisqacha takror berib turish foydali."]', '["Tinglovchilarga 5-7 daqiqada bir savol berish — diqqatni saqlaydi.","Uy vazifasi sifatida 2-3 ta savol berish va keyingi darsda ko''rib chiqish.","Eng oddiy misoldan boshlab keyingi qadamga o''tish — barcha o''quvchilar bilan bir tezlikda yurishga yordam beradi."]', '2026-06-18 12:37:00');
INSERT INTO lessons (id, user_id, group_name, topic, course_type, duration_seconds, transcript, created_at) VALUES (1071, 1008, 'SI-101', 'IN — Misollar va tahlil', 'Iqtisodiyot nazariyasi', 4312, 'Talab va taklif qonuni — bozor iqtisodiyotining asosi. Talab — xaridorlar ma''lum narxda sotib olishga tayyor bo''lgan miqdor. Taklif — sotuvchilar shu narxda sotishga tayyor miqdor.

Narx oshganda talab odatda kamayadi (ters proportsional). Taklif esa oshadi — sotuvchilar ko''proq daromad olish uchun ko''proq taklif qiladilar. Ikkala chiziq kesishgan nuqta — muvozanat narxi.

Elastiklik — narx o''zgarganda talab qancha o''zgarishini ko''rsatadi. Asosiy mahsulotlar (non, suv) noelastik — narx oshsa ham deyarli xuddi shuncha sotib olinadi. Hashamatli mollar elastik.

Davlat narxlarni belgilashi mumkin: maksimum (tomon) yoki minimum (yer). Lekin bu ko''pincha tanqislikni yoki ortiqcha taklifni keltirib chiqaradi. Erkin bozor odatda samaraliroq, lekin nazoratsiz qoldirish ham xavfli.', '2026-06-01 15:00:00');
INSERT INTO evaluations (lesson_id, overall_score, topic_score, speech_score, method_score, interaction_score, feedback_score, summary, strengths, improvements, advice, created_at) VALUES (1071, 80, 15, 17, 14, 16, 18, 'Mazmun va shaklning yaxshi muvozanati. Misollar mavzuni qo''llab-quvvatlaydi.', '["Real hayotdagi misollar yordamida nazariya mustahkamlandi.","O''quvchilar bilan o''zaro muloqot yaxshi tashkil etilgan."]', '["Tezlikni biroz pasaytirish — ayrim joylar tez o''tib ketdi.","Murakkab atamalar uchun qisqacha takror berib turish foydali."]', '["Darsda Q&A vaqti aniq belgilash — talabalar savol berishdan tortinmasin.","Muhim atamalarni taxtaga yozib qo''yish — eslab qolishni osonlashtiradi."]', '2026-06-01 15:00:00');
