INSERT INTO evaluations (lesson_id, overall_score, topic_score, speech_score, method_score, interaction_score, feedback_score, summary, strengths, improvements, advice, created_at) VALUES (1074, 75, 13, 17, 13, 17, 15, 'O''rtacha sifatdagi dars — mavzu qamrab olindi, lekin o''quvchilar reaktsiyasiga ko''p e''tibor berilmadi.', '["Ovoz baland va aniq, jaranglashi yaxshi.","O''quvchilar bilan o''zaro muloqot yaxshi tashkil etilgan."]', '["O''quvchilarga savollar berib qatnashtirish keng bo''lishi kerak.","Murakkab atamalar uchun qisqacha takror berib turish foydali.","Ko''proq amaliy mashqlar berilsa yaxshi bo''lardi."]', '["Har dars boshida 1-2 daqiqa o''tgan darsni qaytarish — yaxshi natija beradi.","Eng oddiy misoldan boshlab keyingi qadamga o''tish — barcha o''quvchilar bilan bir tezlikda yurishga yordam beradi.","Uy vazifasi sifatida 2-3 ta savol berish va keyingi darsda ko''rib chiqish."]', '2026-06-10 16:52:00');
INSERT INTO lessons (id, user_id, group_name, topic, course_type, duration_seconds, transcript, created_at) VALUES (1075, 1004, 'SI-101', 'SIA — Yangi mavzu kirishi', 'Sun''iy intellekt asoslari', 2490, 'Sun''iy intellekt nima va nima emas? Bugun biz aniq belgilab olamiz. AI — bu kompyuter sistemalari odam aql talab qiladigan vazifalarni bajarishi. Lekin bu film kabi sezuvchi mavjudot emas.

AI ning uch katta turi bor: tor AI (narrow) — bitta vazifani bajaruvchi, masalan shaxmat dasturi yoki yuzni tanish. Umumiy AI (AGI) — odam kabi har xil vazifalarni bajarish, hozircha mavjud emas. Super AI — odamdan o''tib ketish, faqat fantastikada.

Bugungi barcha mashhur tizimlar — ChatGPT, Gemini, Midjourney — tor AI. Ular ma''lum vazifaga juda yaxshi javob beradi, lekin tushunish va ong yo''q. Asosida statistika va naqshlarni topish.

Mashinaviy o''rganish — bu AI ni yaratishning asosiy yo''li. Dasturchi qoidalarni yozmaydi, balki misollar beradi va sistema o''zi naqshni topadi. Keyingi darsda biz neyron tarmoqlar haqida gaplashamiz.', '2026-06-19 11:06:00');
INSERT INTO evaluations (lesson_id, overall_score, topic_score, speech_score, method_score, interaction_score, feedback_score, summary, strengths, improvements, advice, created_at) VALUES (1075, 68, 13, 12, 14, 16, 13, 'Asosiy mavzu yetkazildi, lekin tushuntirishda ba''zi joylar tezroq o''tib ketdi.', '["Real hayotdagi misollar yordamida nazariya mustahkamlandi.","Misollar amaliy va o''quvchilarga tushunarli.","Tushunchalar bosqichma-bosqich oddiydan murakkabga qarab tushuntirildi."]', '["Ko''proq amaliy mashqlar berilsa yaxshi bo''lardi.","Murakkab atamalar uchun qisqacha takror berib turish foydali."]', '["Muhim atamalarni taxtaga yozib qo''yish — eslab qolishni osonlashtiradi.","Har dars boshida 1-2 daqiqa o''tgan darsni qaytarish — yaxshi natija beradi."]', '2026-06-19 11:06:00');
