INSERT INTO evaluations (lesson_id, overall_score, topic_score, speech_score, method_score, interaction_score, feedback_score, summary, strengths, improvements, advice, created_at) VALUES (1081, 75, 14, 16, 14, 17, 14, 'Asosiy mavzu yetkazildi, lekin tushuntirishda ba''zi joylar tezroq o''tib ketdi.', '["Misollar amaliy va o''quvchilarga tushunarli.","Vizual yoki yozma misollar kontsentratsiyaga yordam berdi.","Tushunchalar bosqichma-bosqich oddiydan murakkabga qarab tushuntirildi."]', '["O''quvchilarga savollar berib qatnashtirish keng bo''lishi kerak.","Dars oxirida qisqa xulosa va kalit fikrlarni qaytarish."]', '["Muhim atamalarni taxtaga yozib qo''yish — eslab qolishni osonlashtiradi.","Darsda Q&A vaqti aniq belgilash — talabalar savol berishdan tortinmasin.","Uy vazifasi sifatida 2-3 ta savol berish va keyingi darsda ko''rib chiqish."]', '2026-06-04 10:58:00');
INSERT INTO lessons (id, user_id, group_name, topic, course_type, duration_seconds, transcript, created_at) VALUES (1082, 1007, 'SI-201', 'DM — Loyiha taqdimoti', 'Diskret matematika', 3533, 'Bugungi mavzu — to''plamlar va ulardagi amallar. To''plam — bu aniq belgilangan obyektlar yig''indisi. A = {1, 2, 3} kabi yoziladi. Element to''plamga tegishli yoki tegishli emas.

Asosiy amallar: birlashma (A∪B) — barcha elementlar; kesishma (A∩B) — umumiy elementlar; ayirma (A\B) — A da bor lekin B da yo''q; to''ldiruvchi — universal to''plamdagi qolganlar.

Kuchli to''plam (power set) — berilgan to''plamning barcha qism to''plamlari to''plami. Agar A = {a, b} bo''lsa, P(A) = {∅, {a}, {b}, {a,b}}. Ya''ni 2^n ta element bo''ladi.

Vennin diagrammasi to''plam munosabatlarini vizualizatsiya qilish uchun ajoyib vosita. Ikki yoki uchta to''plam uchun yaxshi ishlaydi. Mantiqiy fikrlashda ham qo''l keladi: "barcha A — B" degani A ⊆ B.', '2026-06-26 12:12:00');
INSERT INTO evaluations (lesson_id, overall_score, topic_score, speech_score, method_score, interaction_score, feedback_score, summary, strengths, improvements, advice, created_at) VALUES (1082, 65, 12, 12, 14, 13, 14, 'Dars umumiy ma''noda yaxshi olib borildi, lekin amaliy qism va o''quvchilarni jalb qilish kuchaytirilishi kerak.', '["Tushunchalar bosqichma-bosqich oddiydan murakkabga qarab tushuntirildi.","Ovoz baland va aniq, jaranglashi yaxshi.","Misollar amaliy va o''quvchilarga tushunarli."]', '["Dars oxirida qisqa xulosa va kalit fikrlarni qaytarish.","Murakkab atamalar uchun qisqacha takror berib turish foydali."]', '["Muhim atamalarni taxtaga yozib qo''yish — eslab qolishni osonlashtiradi.","Tinglovchilarga 5-7 daqiqada bir savol berish — diqqatni saqlaydi.","Darsda Q&A vaqti aniq belgilash — talabalar savol berishdan tortinmasin."]', '2026-06-26 12:12:00');
