INSERT INTO lessons (id, user_id, group_name, topic, course_type, duration_seconds, transcript, created_at) VALUES (1088, 1005, 'SI-201', 'MO — Yechimlar muhokamasi', 'Mashinaviy o''rganish', 3338, 'Linear regressiya — eng oddiy va eng asosiy ML algoritm. Maqsadi: kirish (X) va chiqish (y) o''rtasidagi chiziqli bog''liqlikni topish.

Formula: y = wx + b. Bu yerda w og''irlik (slope), b bias (intercept). Ma''lumotlar asosida w va b qiymatlarini topishimiz kerak. Bu uchun yo''qotish funksiyasini (loss function) minimallashtiramiz.

Eng ko''p ishlatiladigan loss — Mean Squared Error: barcha xatolarning kvadratlari o''rtachasi. Gradient descent algoritmi bilan loss ni kamaytiramiz, har qadamda w va b ni biroz o''zgartiramiz.

scikit-learn kutubxonasi bilan amalga oshirish juda oson: from sklearn.linear_model import LinearRegression, model = LinearRegression(), model.fit(X, y). Lekin asosini tushunish muhim — boshqa algoritmlar shu printsipga asoslangan.', '2026-06-11 10:34:00');
INSERT INTO evaluations (lesson_id, overall_score, topic_score, speech_score, method_score, interaction_score, feedback_score, summary, strengths, improvements, advice, created_at) VALUES (1088, 81, 17, 15, 20, 15, 14, 'Dars yaxshi tashkil etilgan, mavzu chuqur va aniq yoritilgan. O''quvchilar bilan muloqot mustahkam.', '["Vizual yoki yozma misollar kontsentratsiyaga yordam berdi.","O''quvchilar bilan o''zaro muloqot yaxshi tashkil etilgan."]', '["Murakkab atamalar uchun qisqacha takror berib turish foydali.","Yozma misollarni daftar yoki taxta orqali ko''rsatish."]', '["Tinglovchilarga 5-7 daqiqada bir savol berish — diqqatni saqlaydi.","Darsda Q&A vaqti aniq belgilash — talabalar savol berishdan tortinmasin."]', '2026-06-11 10:34:00');
