INSERT INTO evaluations (lesson_id, overall_score, topic_score, speech_score, method_score, interaction_score, feedback_score, summary, strengths, improvements, advice, created_at) VALUES (1099, 56, 9, 13, 10, 14, 10, 'Dars sxematik o''tdi — o''quvchilar bilan muloqot deyarli yo''q edi.', '["Mavzu aniq va izchil yoritildi.","Tushunchalar bosqichma-bosqich oddiydan murakkabga qarab tushuntirildi."]', '["Yozma misollarni daftar yoki taxta orqali ko''rsatish.","Dars oxirida qisqa xulosa va kalit fikrlarni qaytarish."]', '["Eng oddiy misoldan boshlab keyingi qadamga o''tish — barcha o''quvchilar bilan bir tezlikda yurishga yordam beradi.","Muhim atamalarni taxtaga yozib qo''yish — eslab qolishni osonlashtiradi."]', '2026-07-16 17:57:00');
INSERT INTO lessons (id, user_id, group_name, topic, course_type, duration_seconds, transcript, created_at) VALUES (1100, 1008, 'MA-101', 'IN — Yangi mavzu kirishi', 'Iqtisodiyot nazariyasi', 4371, 'Talab va taklif qonuni — bozor iqtisodiyotining asosi. Talab — xaridorlar ma''lum narxda sotib olishga tayyor bo''lgan miqdor. Taklif — sotuvchilar shu narxda sotishga tayyor miqdor.

Narx oshganda talab odatda kamayadi (ters proportsional). Taklif esa oshadi — sotuvchilar ko''proq daromad olish uchun ko''proq taklif qiladilar. Ikkala chiziq kesishgan nuqta — muvozanat narxi.

Elastiklik — narx o''zgarganda talab qancha o''zgarishini ko''rsatadi. Asosiy mahsulotlar (non, suv) noelastik — narx oshsa ham deyarli xuddi shuncha sotib olinadi. Hashamatli mollar elastik.

Davlat narxlarni belgilashi mumkin: maksimum (tomon) yoki minimum (yer). Lekin bu ko''pincha tanqislikni yoki ortiqcha taklifni keltirib chiqaradi. Erkin bozor odatda samaraliroq, lekin nazoratsiz qoldirish ham xavfli.', '2026-06-20 11:01:00');
