INSERT INTO evaluations (lesson_id, overall_score, topic_score, speech_score, method_score, interaction_score, feedback_score, summary, strengths, improvements, advice, created_at) VALUES (1103, 55, 9, 14, 9, 12, 11, 'Mavzu yetarlicha chuqur ochilmadi. Misollar va amaliy mashqlar yetishmadi.', '["Ovoz baland va aniq, jaranglashi yaxshi.","Misollar amaliy va o''quvchilarga tushunarli."]', '["O''quvchilarga savollar berib qatnashtirish keng bo''lishi kerak.","Dars oxirida qisqa xulosa va kalit fikrlarni qaytarish."]', '["Har dars boshida 1-2 daqiqa o''tgan darsni qaytarish — yaxshi natija beradi.","Uy vazifasi sifatida 2-3 ta savol berish va keyingi darsda ko''rib chiqish.","Muhim atamalarni taxtaga yozib qo''yish — eslab qolishni osonlashtiradi."]', '2026-07-11 08:56:00');
