INSERT INTO evaluations (lesson_id, overall_score, topic_score, speech_score, method_score, interaction_score, feedback_score, summary, strengths, improvements, advice, created_at) VALUES (1104, 72, 16, 13, 16, 15, 12, 'Dars umumiy ma''noda yaxshi olib borildi, lekin amaliy qism va o''quvchilarni jalb qilish kuchaytirilishi kerak.', '["O''qituvchi savollarga aniq javob berdi.","Ovoz baland va aniq, jaranglashi yaxshi.","Real hayotdagi misollar yordamida nazariya mustahkamlandi."]', '["Dars oxirida qisqa xulosa va kalit fikrlarni qaytarish.","Tezlikni biroz pasaytirish — ayrim joylar tez o''tib ketdi.","Tushuntirish boshlanishida darsning maqsadi aniq aytilishi kerak."]', '["Tinglovchilarga 5-7 daqiqada bir savol berish — diqqatni saqlaydi.","Real loyiha yoki amaliy vazifa qo''shish — motivatsiyani oshiradi."]', '2026-07-20 13:21:00');
INSERT INTO lessons (id, user_id, group_name, topic, course_type, duration_seconds, transcript, created_at) VALUES (1105, 1006, 'MA-201', 'KT — Yangi mavzu kirishi', 'Kompyuter tarmoqlari', 2422, 'OSI modeli — tarmoqni tushunish uchun asos. 7 ta qatlamdan iborat: physical, data link, network, transport, session, presentation, application. Har biri o''z vazifasiga ega.

Physical qatlami — kabel, signal, voltaj. Data link — MAC manzillar, Ethernet. Network qatlami — IP manzillar va routing. Transport — TCP yoki UDP, port raqamlari.

TCP — ishonchli aloqa, ma''lumotlar to''liq yetkazilganini ta''minlaydi. UDP — tez lekin ishonchsiz, video oqim va o''yinlar uchun mos. Application qatlami — HTTP, FTP, DNS kabi protokollar.

Amaliyotda har doim 7 qatlamni alohida ko''rmaymiz, lekin muammoni tashxis qilishda OSI modeli yordam beradi. "Ping" ishlamayapti — birinchi physical va data link tekshiriladi. "DNS" muammo — application qatlami.', '2026-07-18 15:04:00');
