INSERT INTO lessons (id, user_id, group_name, topic, course_type, duration_seconds, transcript, created_at) VALUES (1111, 1000, 'MA-201', 'DA — Misollar va tahlil', 'Dasturlash asoslari', 1235, 'Salom o''quvchilar. Bugungi darsimizda biz o''zgaruvchilar va ularning turlari haqida gaplashamiz. O''zgaruvchi — bu ma''lumotni saqlash uchun nomli xotira maydoni. Python tilida o''zgaruvchini e''lon qilish uchun ismni yozib, teng belgisidan keyin qiymatni kiritamiz.

Misol uchun: yosh = 20. Bu yerda yosh degan o''zgaruvchiga 20 qiymati berildi. Endi keling turlarga e''tibor beraylik. Asosan to''rtta turdagi ma''lumot bor: int — butun sonlar, float — kasr sonlar, str — matn, va bool — rost yoki yolg''on qiymatlar.

Type funksiyasi orqali o''zgaruvchining turini bilib olishimiz mumkin. Print(type(yosh)) deb yozsak, ekranda class int chiqadi. Bu Python avtomatik ravishda turini aniqlaganini ko''rsatadi.

Endi sizga vazifa: o''z ismingiz va yoshingizni ifodalaydigan ikki o''zgaruvchi yarating va ekranga chiqaring. Keyingi darsda biz shartli operatorlarni o''rganamiz.', '2026-07-12 12:23:00');
INSERT INTO evaluations (lesson_id, overall_score, topic_score, speech_score, method_score, interaction_score, feedback_score, summary, strengths, improvements, advice, created_at) VALUES (1111, 49, 10, 11, 10, 8, 10, 'Tushuntirish nomuvofiq, ba''zi muhim joylar o''tkazib yuborildi.', '["Ovoz baland va aniq, jaranglashi yaxshi.","Vizual yoki yozma misollar kontsentratsiyaga yordam berdi.","Tushunchalar bosqichma-bosqich oddiydan murakkabga qarab tushuntirildi."]', '["O''quvchilarga savollar berib qatnashtirish keng bo''lishi kerak.","Ko''proq amaliy mashqlar berilsa yaxshi bo''lardi."]', '["Eng oddiy misoldan boshlab keyingi qadamga o''tish — barcha o''quvchilar bilan bir tezlikda yurishga yordam beradi.","Real loyiha yoki amaliy vazifa qo''shish — motivatsiyani oshiradi."]', '2026-07-12 12:23:00');
