INSERT INTO evaluations (lesson_id, overall_score, topic_score, speech_score, method_score, interaction_score, feedback_score, summary, strengths, improvements, advice, created_at) VALUES (1114, 66, 11, 15, 16, 14, 10, 'Asosiy mavzu yetkazildi, lekin tushuntirishda ba''zi joylar tezroq o''tib ketdi.', '["Ovoz baland va aniq, jaranglashi yaxshi.","Real hayotdagi misollar yordamida nazariya mustahkamlandi.","O''qituvchi savollarga aniq javob berdi."]', '["Murakkab atamalar uchun qisqacha takror berib turish foydali.","Dars oxirida qisqa xulosa va kalit fikrlarni qaytarish.","Tushuntirish boshlanishida darsning maqsadi aniq aytilishi kerak."]', '["Eng oddiy misoldan boshlab keyingi qadamga o''tish — barcha o''quvchilar bilan bir tezlikda yurishga yordam beradi.","Uy vazifasi sifatida 2-3 ta savol berish va keyingi darsda ko''rib chiqish."]', '2026-06-14 08:48:00');
INSERT INTO lessons (id, user_id, group_name, topic, course_type, duration_seconds, transcript, created_at) VALUES (1115, 1000, 'MA-201', 'DA — Misollar va tahlil', 'Dasturlash asoslari', 4160, 'Salom o''quvchilar. Bugungi darsimizda biz o''zgaruvchilar va ularning turlari haqida gaplashamiz. O''zgaruvchi — bu ma''lumotni saqlash uchun nomli xotira maydoni. Python tilida o''zgaruvchini e''lon qilish uchun ismni yozib, teng belgisidan keyin qiymatni kiritamiz.

Misol uchun: yosh = 20. Bu yerda yosh degan o''zgaruvchiga 20 qiymati berildi. Endi keling turlarga e''tibor beraylik. Asosan to''rtta turdagi ma''lumot bor: int — butun sonlar, float — kasr sonlar, str — matn, va bool — rost yoki yolg''on qiymatlar.

Type funksiyasi orqali o''zgaruvchining turini bilib olishimiz mumkin. Print(type(yosh)) deb yozsak, ekranda class int chiqadi. Bu Python avtomatik ravishda turini aniqlaganini ko''rsatadi.

Endi sizga vazifa: o''z ismingiz va yoshingizni ifodalaydigan ikki o''zgaruvchi yarating va ekranga chiqaring. Keyingi darsda biz shartli operatorlarni o''rganamiz.', '2026-06-29 16:43:00');
INSERT INTO evaluations (lesson_id, overall_score, topic_score, speech_score, method_score, interaction_score, feedback_score, summary, strengths, improvements, advice, created_at) VALUES (1115, 59, 10, 12, 13, 15, 9, 'Dars sxematik o''tdi — o''quvchilar bilan muloqot deyarli yo''q edi.', '["Ovoz baland va aniq, jaranglashi yaxshi.","Vizual yoki yozma misollar kontsentratsiyaga yordam berdi.","Real hayotdagi misollar yordamida nazariya mustahkamlandi."]', '["Ko''proq amaliy mashqlar berilsa yaxshi bo''lardi.","Dars oxirida qisqa xulosa va kalit fikrlarni qaytarish."]', '["Har dars boshida 1-2 daqiqa o''tgan darsni qaytarish — yaxshi natija beradi.","Darsda Q&A vaqti aniq belgilash — talabalar savol berishdan tortinmasin."]', '2026-06-29 16:43:00');
