INSERT INTO evaluations (lesson_id, overall_score, topic_score, speech_score, method_score, interaction_score, feedback_score, summary, strengths, improvements, advice, created_at) VALUES (1116, 60, 11, 15, 14, 10, 10, 'Asosiy mavzu yetkazildi, lekin tushuntirishda ba''zi joylar tezroq o''tib ketdi.', '["Mavzu aniq va izchil yoritildi.","Misollar amaliy va o''quvchilarga tushunarli.","Tushunchalar bosqichma-bosqich oddiydan murakkabga qarab tushuntirildi."]', '["O''quvchilarga savollar berib qatnashtirish keng bo''lishi kerak.","Murakkab atamalar uchun qisqacha takror berib turish foydali."]', '["Muhim atamalarni taxtaga yozib qo''yish — eslab qolishni osonlashtiradi.","Real loyiha yoki amaliy vazifa qo''shish — motivatsiyani oshiradi.","Darsda Q&A vaqti aniq belgilash — talabalar savol berishdan tortinmasin."]', '2026-06-03 09:44:00');
INSERT INTO lessons (id, user_id, group_name, topic, course_type, duration_seconds, transcript, created_at) VALUES (1117, 1004, 'RI-101', 'SIA — Asosiy tushunchalar', 'Sun''iy intellekt asoslari', 4197, 'Sun''iy intellekt nima va nima emas? Bugun biz aniq belgilab olamiz. AI — bu kompyuter sistemalari odam aql talab qiladigan vazifalarni bajarishi. Lekin bu film kabi sezuvchi mavjudot emas.

AI ning uch katta turi bor: tor AI (narrow) — bitta vazifani bajaruvchi, masalan shaxmat dasturi yoki yuzni tanish. Umumiy AI (AGI) — odam kabi har xil vazifalarni bajarish, hozircha mavjud emas. Super AI — odamdan o''tib ketish, faqat fantastikada.

Bugungi barcha mashhur tizimlar — ChatGPT, Gemini, Midjourney — tor AI. Ular ma''lum vazifaga juda yaxshi javob beradi, lekin tushunish va ong yo''q. Asosida statistika va naqshlarni topish.

Mashinaviy o''rganish — bu AI ni yaratishning asosiy yo''li. Dasturchi qoidalarni yozmaydi, balki misollar beradi va sistema o''zi naqshni topadi. Keyingi darsda biz neyron tarmoqlar haqida gaplashamiz.', '2026-07-22 11:17:00');
INSERT INTO evaluations (lesson_id, overall_score, topic_score, speech_score, method_score, interaction_score, feedback_score, summary, strengths, improvements, advice, created_at) VALUES (1117, 57, 11, 11, 12, 13, 10, 'Mavzu yetarlicha chuqur ochilmadi. Misollar va amaliy mashqlar yetishmadi.', '["Misollar amaliy va o''quvchilarga tushunarli.","Vizual yoki yozma misollar kontsentratsiyaga yordam berdi."]', '["Murakkab atamalar uchun qisqacha takror berib turish foydali.","Dars oxirida qisqa xulosa va kalit fikrlarni qaytarish.","Ko''proq amaliy mashqlar berilsa yaxshi bo''lardi."]', '["Darsda Q&A vaqti aniq belgilash — talabalar savol berishdan tortinmasin.","Muhim atamalarni taxtaga yozib qo''yish — eslab qolishni osonlashtiradi.","Har dars boshida 1-2 daqiqa o''tgan darsni qaytarish — yaxshi natija beradi."]', '2026-07-22 11:17:00');
