INSERT INTO evaluations (lesson_id, overall_score, topic_score, speech_score, method_score, interaction_score, feedback_score, summary, strengths, improvements, advice, created_at) VALUES (1124, 45, 9, 10, 9, 8, 9, 'Mavzu yetarlicha chuqur ochilmadi. Misollar va amaliy mashqlar yetishmadi.', '["Ovoz baland va aniq, jaranglashi yaxshi.","Vizual yoki yozma misollar kontsentratsiyaga yordam berdi."]', '["Yozma misollarni daftar yoki taxta orqali ko''rsatish.","Tushuntirish boshlanishida darsning maqsadi aniq aytilishi kerak."]', '["Tinglovchilarga 5-7 daqiqada bir savol berish — diqqatni saqlaydi.","Uy vazifasi sifatida 2-3 ta savol berish va keyingi darsda ko''rib chiqish."]', '2026-07-11 16:00:00');
