INSERT INTO evaluations (lesson_id, overall_score, topic_score, speech_score, method_score, interaction_score, feedback_score, summary, strengths, improvements, advice, created_at) VALUES (1126, 74, 15, 16, 11, 16, 16, 'O''rtacha sifatdagi dars — mavzu qamrab olindi, lekin o''quvchilar reaktsiyasiga ko''p e''tibor berilmadi.', '["O''quvchilar bilan o''zaro muloqot yaxshi tashkil etilgan.","Vizual yoki yozma misollar kontsentratsiyaga yordam berdi.","O''qituvchi savollarga aniq javob berdi."]', '["Tushuntirish boshlanishida darsning maqsadi aniq aytilishi kerak.","O''quvchilarga savollar berib qatnashtirish keng bo''lishi kerak."]', '["Uy vazifasi sifatida 2-3 ta savol berish va keyingi darsda ko''rib chiqish.","Tinglovchilarga 5-7 daqiqada bir savol berish — diqqatni saqlaydi."]', '2026-06-13 12:42:00');
INSERT INTO lessons (id, user_id, group_name, topic, course_type, duration_seconds, transcript, created_at) VALUES (1127, 1000, 'RI-201', 'DA — Test va o''zlashtirish', 'Dasturlash asoslari', 1930, 'Funksiyalar — bu kodni qayta ishlatish uchun asosiy vosita. def kalit so''zi bilan funksiyani aniqlaymiz. Argumentlar qavslar ichida, return orqali qiymat qaytariladi.

Misol uchun, ikki sonni qo''shadigan funksiya: def yigindi(a, b): return a + b. Endi bu funksiyani istalgan joyda chaqirsak bo''ladi: natija = yigindi(5, 3). Bu yerda 8 qaytariladi.

Default argumentlar ham mavjud. Agar argument berilmasa, default qiymat ishlatiladi. Misol: def salom(ism="dunyo"): print("Salom", ism). Salom() chaqirilganda "Salom dunyo" chiqadi.

Funksiya nomlari mazmunli bo''lishi kerak. yigindi, ko_paytma, foiz_hisobla — bularning hammasi yaxshi nomlar. f1, x, abc — yomon nomlar. Yaxshi kod yozish — bu o''qilishi oson kod yozish.', '2026-05-27 13:03:00');
INSERT INTO evaluations (lesson_id, overall_score, topic_score, speech_score, method_score, interaction_score, feedback_score, summary, strengths, improvements, advice, created_at) VALUES (1127, 64, 13, 12, 15, 11, 13, 'Dars umumiy ma''noda yaxshi olib borildi, lekin amaliy qism va o''quvchilarni jalb qilish kuchaytirilishi kerak.', '["Misollar amaliy va o''quvchilarga tushunarli.","Tushunchalar bosqichma-bosqich oddiydan murakkabga qarab tushuntirildi.","O''quvchilar bilan o''zaro muloqot yaxshi tashkil etilgan."]', '["O''quvchilarga savollar berib qatnashtirish keng bo''lishi kerak.","Ko''proq amaliy mashqlar berilsa yaxshi bo''lardi.","Tezlikni biroz pasaytirish — ayrim joylar tez o''tib ketdi."]', '["Muhim atamalarni taxtaga yozib qo''yish — eslab qolishni osonlashtiradi.","Eng oddiy misoldan boshlab keyingi qadamga o''tish — barcha o''quvchilar bilan bir tezlikda yurishga yordam beradi."]', '2026-05-27 13:03:00');
INSERT INTO lessons (id, user_id, group_name, topic, course_type, duration_seconds, transcript, created_at) VALUES (1128, 1000, 'RI-201', 'DA — Yechimlar muhokamasi', 'Dasturlash asoslari', 1834, 'Funksiyalar — bu kodni qayta ishlatish uchun asosiy vosita. def kalit so''zi bilan funksiyani aniqlaymiz. Argumentlar qavslar ichida, return orqali qiymat qaytariladi.

