INSERT INTO evaluations (lesson_id, overall_score, topic_score, speech_score, method_score, interaction_score, feedback_score, summary, strengths, improvements, advice, created_at) VALUES (1131, 65, 11, 14, 13, 13, 14, 'O''rtacha sifatdagi dars — mavzu qamrab olindi, lekin o''quvchilar reaktsiyasiga ko''p e''tibor berilmadi.', '["Tushunchalar bosqichma-bosqich oddiydan murakkabga qarab tushuntirildi.","O''quvchilar bilan o''zaro muloqot yaxshi tashkil etilgan.","Mavzu aniq va izchil yoritildi."]', '["Ko''proq amaliy mashqlar berilsa yaxshi bo''lardi.","Tushuntirish boshlanishida darsning maqsadi aniq aytilishi kerak.","Murakkab atamalar uchun qisqacha takror berib turish foydali."]', '["Har dars boshida 1-2 daqiqa o''tgan darsni qaytarish — yaxshi natija beradi.","Real loyiha yoki amaliy vazifa qo''shish — motivatsiyani oshiradi."]', '2026-06-26 16:22:00');
INSERT INTO lessons (id, user_id, group_name, topic, course_type, duration_seconds, transcript, created_at) VALUES (1132, 1000, 'RI-201', 'DA — Yechimlar muhokamasi', 'Dasturlash asoslari', 3303, 'Bugun shartli operatorlar mavzusiga to''xtalamiz. Dastur har doim chiziqli bajarilmaydi — ba''zan biz uning yo''nalishini boshqarishimiz kerak. Buning uchun if konstruksiyasidan foydalanamiz.

Sintaksisi juda oddiy: if shart, keyin ikki nuqta, va keyingi qatorda tabulyatsiya bilan bajariladigan kod. Misol: if yosh >= 18: print("Voyaga yetgan"). Agar shart bajarilmasa, else bloki ishlaydi.

Bir nechta shartlarni tekshirish uchun elif kalit so''zi bor. Masalan: if score >= 90 print("a''lo"), elif score >= 70 print("yaxshi"), else print("qoniqarli"). Ushbu konstruksiya darslar bahosini aniqlash uchun ko''p ishlatiladi.

Operator and, or, not yordamida murakkab shartlar tuzish mumkin. Eslatib o''taman: Python da indentatsiya juda muhim — agar bo''shliqlar to''g''ri qo''yilmasa, dastur xato beradi.', '2026-06-09 12:01:00');
INSERT INTO evaluations (lesson_id, overall_score, topic_score, speech_score, method_score, interaction_score, feedback_score, summary, strengths, improvements, advice, created_at) VALUES (1132, 75, 17, 17, 15, 12, 14, 'O''rtacha sifatdagi dars — mavzu qamrab olindi, lekin o''quvchilar reaktsiyasiga ko''p e''tibor berilmadi.', '["O''quvchilar bilan o''zaro muloqot yaxshi tashkil etilgan.","Misollar amaliy va o''quvchilarga tushunarli."]', '["Tushuntirish boshlanishida darsning maqsadi aniq aytilishi kerak.","Yozma misollarni daftar yoki taxta orqali ko''rsatish.","Tezlikni biroz pasaytirish — ayrim joylar tez o''tib ketdi."]', '["Darsda Q&A vaqti aniq belgilash — talabalar savol berishdan tortinmasin.","Har dars boshida 1-2 daqiqa o''tgan darsni qaytarish — yaxshi natija beradi."]', '2026-06-09 12:01:00');
INSERT INTO lessons (id, user_id, group_name, topic, course_type, duration_seconds, transcript, created_at) VALUES (1133, 1000, 'RI-201', 'DA — Yechimlar muhokamasi', 'Dasturlash asoslari', 1807, 'Bugun shartli operatorlar mavzusiga to''xtalamiz. Dastur har doim chiziqli bajarilmaydi — ba''zan biz uning yo''nalishini boshqarishimiz kerak. Buning uchun if konstruksiyasidan foydalanamiz.

Sintaksisi juda oddiy: if shart, keyin ikki nuqta, va keyingi qatorda tabulyatsiya bilan bajariladigan kod. Misol: if yosh >= 18: print("Voyaga yetgan"). Agar shart bajarilmasa, else bloki ishlaydi.

Bir nechta shartlarni tekshirish uchun elif kalit so''zi bor. Masalan: if score >= 90 print("a''lo"), elif score >= 70 print("yaxshi"), else print("qoniqarli"). Ushbu konstruksiya darslar bahosini aniqlash uchun ko''p ishlatiladi.

Operator and, or, not yordamida murakkab shartlar tuzish mumkin. Eslatib o''taman: Python da indentatsiya juda muhim — agar bo''shliqlar to''g''ri qo''yilmasa, dastur xato beradi.', '2026-07-07 17:24:00');
INSERT INTO evaluations (lesson_id, overall_score, topic_score, speech_score, method_score, interaction_score, feedback_score, summary, strengths, improvements, advice, created_at) VALUES (1133, 56, 11, 13, 13, 9, 10, 'Dars sxematik o''tdi — o''quvchilar bilan muloqot deyarli yo''q edi.', '["Ovoz baland va aniq, jaranglashi yaxshi.","Misollar amaliy va o''quvchilarga tushunarli."]', '["Tezlikni biroz pasaytirish — ayrim joylar tez o''tib ketdi.","Tushuntirish boshlanishida darsning maqsadi aniq aytilishi kerak.","Ko''proq amaliy mashqlar berilsa yaxshi bo''lardi."]', '["Muhim atamalarni taxtaga yozib qo''yish — eslab qolishni osonlashtiradi.","Har dars boshida 1-2 daqiqa o''tgan darsni qaytarish — yaxshi natija beradi.","Darsda Q&A vaqti aniq belgilash — talabalar savol berishdan tortinmasin."]', '2026-07-07 17:24:00');
INSERT INTO lessons (id, user_id, group_name, topic, course_type, duration_seconds, transcript, created_at) VALUES (1134, 1006, 'RI-201', 'KT — Test va o''zlashtirish', 'Kompyuter tarmoqlari', 1447, 'OSI modeli — tarmoqni tushunish uchun asos. 7 ta qatlamdan iborat: physical, data link, network, transport, session, presentation, application. Har biri o''z vazifasiga ega.

Physical qatlami — kabel, signal, voltaj. Data link — MAC manzillar, Ethernet. Network qatlami — IP manzillar va routing. Transport — TCP yoki UDP, port raqamlari.

TCP — ishonchli aloqa, ma''lumotlar to''liq yetkazilganini ta''minlaydi. UDP — tez lekin ishonchsiz, video oqim va o''yinlar uchun mos. Application qatlami — HTTP, FTP, DNS kabi protokollar.

Amaliyotda har doim 7 qatlamni alohida ko''rmaymiz, lekin muammoni tashxis qilishda OSI modeli yordam beradi. "Ping" ishlamayapti — birinchi physical va data link tekshiriladi. "DNS" muammo — application qatlami.', '2026-07-10 16:33:00');
INSERT INTO evaluations (lesson_id, overall_score, topic_score, speech_score, method_score, interaction_score, feedback_score, summary, strengths, improvements, advice, created_at) VALUES (1134, 67, 12, 12, 15, 15, 13, 'Dars umumiy ma''noda yaxshi olib borildi, lekin amaliy qism va o''quvchilarni jalb qilish kuchaytirilishi kerak.', '["Vizual yoki yozma misollar kontsentratsiyaga yordam berdi.","Tushunchalar bosqichma-bosqich oddiydan murakkabga qarab tushuntirildi.","O''qituvchi savollarga aniq javob berdi."]', '["Tezlikni biroz pasaytirish — ayrim joylar tez o''tib ketdi.","O''quvchilarga savollar berib qatnashtirish keng bo''lishi kerak.","Tushuntirish boshlanishida darsning maqsadi aniq aytilishi kerak."]', '["Darsda Q&A vaqti aniq belgilash — talabalar savol berishdan tortinmasin.","Har dars boshida 1-2 daqiqa o''tgan darsni qaytarish — yaxshi natija beradi.","Real loyiha yoki amaliy vazifa qo''shish — motivatsiyani oshiradi."]', '2026-07-10 16:33:00');
INSERT INTO lessons (id, user_id, group_name, topic, course_type, duration_seconds, transcript, created_at) VALUES (1135, 1006, 'RI-201', 'KT — Asosiy tushunchalar', 'Kompyuter tarmoqlari', 2466, 'OSI modeli — tarmoqni tushunish uchun asos. 7 ta qatlamdan iborat: physical, data link, network, transport, session, presentation, application. Har biri o''z vazifasiga ega.

