INSERT INTO evaluations (lesson_id, overall_score, topic_score, speech_score, method_score, interaction_score, feedback_score, summary, strengths, improvements, advice, created_at) VALUES (1135, 91, 19, 19, 20, 15, 18, 'Dars yaxshi tashkil etilgan, mavzu chuqur va aniq yoritilgan. O''quvchilar bilan muloqot mustahkam.', '["Misollar amaliy va o''quvchilarga tushunarli.","O''qituvchi savollarga aniq javob berdi.","Mavzu aniq va izchil yoritildi."]', '["O''quvchilarga savollar berib qatnashtirish keng bo''lishi kerak.","Ko''proq amaliy mashqlar berilsa yaxshi bo''lardi.","Tezlikni biroz pasaytirish — ayrim joylar tez o''tib ketdi."]', '["Real loyiha yoki amaliy vazifa qo''shish — motivatsiyani oshiradi.","Tinglovchilarga 5-7 daqiqada bir savol berish — diqqatni saqlaydi."]', '2026-05-31 15:53:00');
