INSERT INTO evaluations (lesson_id, overall_score, topic_score, speech_score, method_score, interaction_score, feedback_score, summary, strengths, improvements, advice, created_at) VALUES (1148, 70, 13, 16, 18, 11, 12, 'Asosiy mavzu yetkazildi, lekin tushuntirishda ba''zi joylar tezroq o''tib ketdi.', '["O''qituvchi savollarga aniq javob berdi.","Real hayotdagi misollar yordamida nazariya mustahkamlandi.","Vizual yoki yozma misollar kontsentratsiyaga yordam berdi."]', '["O''quvchilarga savollar berib qatnashtirish keng bo''lishi kerak.","Tezlikni biroz pasaytirish — ayrim joylar tez o''tib ketdi.","Tushuntirish boshlanishida darsning maqsadi aniq aytilishi kerak."]', '["Uy vazifasi sifatida 2-3 ta savol berish va keyingi darsda ko''rib chiqish.","Tinglovchilarga 5-7 daqiqada bir savol berish — diqqatni saqlaydi."]', '2026-05-30 17:35:00');
