INSERT INTO evaluations (lesson_id, overall_score, topic_score, speech_score, method_score, interaction_score, feedback_score, summary, strengths, improvements, advice, created_at) VALUES (1149, 74, 17, 14, 13, 17, 13, 'Dars umumiy ma''noda yaxshi olib borildi, lekin amaliy qism va o''quvchilarni jalb qilish kuchaytirilishi kerak.', '["Misollar amaliy va o''quvchilarga tushunarli.","O''qituvchi savollarga aniq javob berdi."]', '["Tezlikni biroz pasaytirish — ayrim joylar tez o''tib ketdi.","Ko''proq amaliy mashqlar berilsa yaxshi bo''lardi."]', '["Tinglovchilarga 5-7 daqiqada bir savol berish — diqqatni saqlaydi.","Uy vazifasi sifatida 2-3 ta savol berish va keyingi darsda ko''rib chiqish."]', '2026-07-12 16:03:00');
