INSERT INTO evaluations (lesson_id, overall_score, topic_score, speech_score, method_score, interaction_score, feedback_score, summary, strengths, improvements, advice, created_at) VALUES (1150, 75, 13, 14, 15, 15, 18, 'Asosiy mavzu yetkazildi, lekin tushuntirishda ba''zi joylar tezroq o''tib ketdi.', '["Misollar amaliy va o''quvchilarga tushunarli.","Ovoz baland va aniq, jaranglashi yaxshi.","O''quvchilar bilan o''zaro muloqot yaxshi tashkil etilgan."]', '["O''quvchilarga savollar berib qatnashtirish keng bo''lishi kerak.","Ko''proq amaliy mashqlar berilsa yaxshi bo''lardi.","Murakkab atamalar uchun qisqacha takror berib turish foydali."]', '["Uy vazifasi sifatida 2-3 ta savol berish va keyingi darsda ko''rib chiqish.","Eng oddiy misoldan boshlab keyingi qadamga o''tish — barcha o''quvchilar bilan bir tezlikda yurishga yordam beradi.","Har dars boshida 1-2 daqiqa o''tgan darsni qaytarish — yaxshi natija beradi."]', '2026-06-28 16:58:00');
