INSERT INTO evaluations (lesson_id, overall_score, topic_score, speech_score, method_score, interaction_score, feedback_score, summary, strengths, improvements, advice, created_at) VALUES (1151, 81, 16, 18, 19, 13, 15, 'Mazmun va shaklning yaxshi muvozanati. Misollar mavzuni qo''llab-quvvatlaydi.', '["Mavzu aniq va izchil yoritildi.","O''quvchilar bilan o''zaro muloqot yaxshi tashkil etilgan."]', '["Ko''proq amaliy mashqlar berilsa yaxshi bo''lardi.","Tezlikni biroz pasaytirish — ayrim joylar tez o''tib ketdi."]', '["Real loyiha yoki amaliy vazifa qo''shish — motivatsiyani oshiradi.","Uy vazifasi sifatida 2-3 ta savol berish va keyingi darsda ko''rib chiqish.","Muhim atamalarni taxtaga yozib qo''yish — eslab qolishni osonlashtiradi."]', '2026-07-04 15:24:00');
INSERT INTO lessons (id, user_id, group_name, topic, course_type, duration_seconds, transcript, created_at) VALUES (1152, 1001, 'RI-101', 'AMT — Misollar va tahlil', 'Algoritmlar va ma''lumotlar tuzilmalari', 3829, 'Stack va Queue — eng asosiy ma''lumotlar tuzilmalari. Stack LIFO printsipida ishlaydi: oxirgi qo''yilgan element birinchi olinadi. Aslida bu plitalar uyumiga o''xshaydi.

Stack uchun ikkita asosiy operatsiya: push — element qo''shish, pop — eng yuqorisini olib tashlash. Ikkalasi ham O(1) vaqtda bajariladi. Foydalanish misollari: brauzerda back tugmasi, undo funksiyasi, qavslarni tekshirish.

Queue esa FIFO: birinchi kelgan birinchi xizmat oladi. Operatsiyalar: enqueue va dequeue. Foydalanish: printer navbati, BFS algoritmi, vazifalar rejalashtiruvchisi.

Python da stack uchun ro''yxat (list) ishlatish mumkin: append va pop. Queue uchun esa collections.deque tavsiya etiladi — chunki ro''yxatda boshidan element olib tashlash O(n) vaqt oladi, deque esa O(1) ta''minlaydi.', '2026-06-28 15:19:00');
INSERT INTO evaluations (lesson_id, overall_score, topic_score, speech_score, method_score, interaction_score, feedback_score, summary, strengths, improvements, advice, created_at) VALUES (1152, 76, 15, 16, 13, 16, 16, 'Dars umumiy ma''noda yaxshi olib borildi, lekin amaliy qism va o''quvchilarni jalb qilish kuchaytirilishi kerak.', '["Tushunchalar bosqichma-bosqich oddiydan murakkabga qarab tushuntirildi.","O''quvchilar bilan o''zaro muloqot yaxshi tashkil etilgan.","Ovoz baland va aniq, jaranglashi yaxshi."]', '["Tezlikni biroz pasaytirish — ayrim joylar tez o''tib ketdi.","Murakkab atamalar uchun qisqacha takror berib turish foydali.","Dars oxirida qisqa xulosa va kalit fikrlarni qaytarish."]', '["Har dars boshida 1-2 daqiqa o''tgan darsni qaytarish — yaxshi natija beradi.","Tinglovchilarga 5-7 daqiqada bir savol berish — diqqatni saqlaydi.","Real loyiha yoki amaliy vazifa qo''shish — motivatsiyani oshiradi."]', '2026-06-28 15:19:00');
INSERT INTO lessons (id, user_id, group_name, topic, course_type, duration_seconds, transcript, created_at) VALUES (1153, 1001, 'RI-101', 'AMT — Asosiy tushunchalar', 'Algoritmlar va ma''lumotlar tuzilmalari', 2509, 'Bugungi mavzuimiz — Big O notatsiyasi. Algoritmni baholash uchun biz uning vaqt va xotira murakkabligini hisoblashimiz kerak. Big O — bu eng yomon holat uchun o''sish darajasini ifodalovchi notatsiya.

O(1) — doimiy vaqt, kirish hajmiga bog''liq emas. Misol: massiv elementiga indeks orqali murojaat. O(n) — chiziqli, kirish hajmiga to''g''ri proporsional. Misol: massivda elementni qidirish.

O(log n) — logarifmik, juda samarali. Klassik misol: ikki bo''lakka bo''lib qidirish (binary search). O(n log n) — yaxshi saralash algoritmlari, masalan merge sort. O(n²) — bubble sort kabi sodda algoritmlar.

Amaliyotda O(n²) algoritmlar 10 ming elementdan ortiq ma''lumotda sezilarli sekinlashadi. Shuning uchun har doim algoritmni tahlil qilib, samaraliroq variantni izlash kerak. Keyingi darsda biz ikki bo''lakka bo''lish algoritmini batafsil ko''rib chiqamiz.', '2026-07-15 09:00:00');
INSERT INTO evaluations (lesson_id, overall_score, topic_score, speech_score, method_score, interaction_score, feedback_score, summary, strengths, improvements, advice, created_at) VALUES (1153, 60, 12, 9, 14, 14, 11, 'O''rtacha sifatdagi dars — mavzu qamrab olindi, lekin o''quvchilar reaktsiyasiga ko''p e''tibor berilmadi.', '["Tushunchalar bosqichma-bosqich oddiydan murakkabga qarab tushuntirildi.","Real hayotdagi misollar yordamida nazariya mustahkamlandi."]', '["Dars oxirida qisqa xulosa va kalit fikrlarni qaytarish.","Tushuntirish boshlanishida darsning maqsadi aniq aytilishi kerak.","Ko''proq amaliy mashqlar berilsa yaxshi bo''lardi."]', '["Darsda Q&A vaqti aniq belgilash — talabalar savol berishdan tortinmasin.","Eng oddiy misoldan boshlab keyingi qadamga o''tish — barcha o''quvchilar bilan bir tezlikda yurishga yordam beradi."]', '2026-07-15 09:00:00');
