INSERT INTO evaluations (lesson_id, overall_score, topic_score, speech_score, method_score, interaction_score, feedback_score, summary, strengths, improvements, advice, created_at) VALUES (1158, 56, 12, 13, 13, 8, 10, 'Dars sxematik o''tdi — o''quvchilar bilan muloqot deyarli yo''q edi.', '["Tushunchalar bosqichma-bosqich oddiydan murakkabga qarab tushuntirildi.","O''qituvchi savollarga aniq javob berdi."]', '["Dars oxirida qisqa xulosa va kalit fikrlarni qaytarish.","Yozma misollarni daftar yoki taxta orqali ko''rsatish.","Tushuntirish boshlanishida darsning maqsadi aniq aytilishi kerak."]', '["Uy vazifasi sifatida 2-3 ta savol berish va keyingi darsda ko''rib chiqish.","Real loyiha yoki amaliy vazifa qo''shish — motivatsiyani oshiradi.","Tinglovchilarga 5-7 daqiqada bir savol berish — diqqatni saqlaydi."]', '2026-07-11 13:03:00');
INSERT INTO lessons (id, user_id, group_name, topic, course_type, duration_seconds, transcript, created_at) VALUES (1159, 1002, 'SI-201', 'VD — Misollar va tahlil', 'Veb dasturlash', 3508, 'Bugun biz HTTP protokolining asoslarini ko''rib chiqamiz. HTTP — bu mijoz va server o''rtasidagi muloqot tili. Brauzer so''rov yuboradi, server javob beradi.

So''rovning uchta asosiy qismi bor: metod, URL, va headerlar. Eng ko''p ishlatiladigan metodlar: GET — ma''lumot olish, POST — yangi ma''lumot yuborish, PUT — yangilash, DELETE — o''chirish. Bularning to''plami RESTful API ning asosini tashkil qiladi.

Status kodlar javobning natijasini bildiradi. 200 — muvaffaqiyat, 201 — yaratildi, 404 — topilmadi, 401 — autentifikatsiya kerak, 500 — server xatosi. Yaxshi API har doim to''g''ri status kod qaytarishi shart.

Bugun amaliy mashq sifatida fetch funksiyasi orqali oddiy API''dan ma''lumot olib, sahifada ko''rsatamiz. JSON formati zamonaviy veb da standart hisoblanadi.', '2026-06-14 15:05:00');
INSERT INTO evaluations (lesson_id, overall_score, topic_score, speech_score, method_score, interaction_score, feedback_score, summary, strengths, improvements, advice, created_at) VALUES (1159, 64, 14, 14, 13, 12, 11, 'Dars umumiy ma''noda yaxshi olib borildi, lekin amaliy qism va o''quvchilarni jalb qilish kuchaytirilishi kerak.', '["O''qituvchi savollarga aniq javob berdi.","Tushunchalar bosqichma-bosqich oddiydan murakkabga qarab tushuntirildi.","Real hayotdagi misollar yordamida nazariya mustahkamlandi."]', '["Tezlikni biroz pasaytirish — ayrim joylar tez o''tib ketdi.","Yozma misollarni daftar yoki taxta orqali ko''rsatish."]', '["Uy vazifasi sifatida 2-3 ta savol berish va keyingi darsda ko''rib chiqish.","Real loyiha yoki amaliy vazifa qo''shish — motivatsiyani oshiradi."]', '2026-06-14 15:05:00');
INSERT INTO lessons (id, user_id, group_name, topic, course_type, duration_seconds, transcript, created_at) VALUES (1160, 1002, 'SI-201', 'VD — Yechimlar muhokamasi', 'Veb dasturlash', 2066, 'React komponentlari haqida gaplashamiz. Komponent — bu UI ning qayta ishlatiladigan qismi. Function komponent eng zamonaviy yondashuv hisoblanadi.

Props orqali komponentga ma''lumot uzatamiz: function Welcome(props) return Salom props.ism. State esa komponentning ichki holati. useState hook orqali boshqarsamiz: const [son setSon] = useState(0).

Komponentlar bir-biriga joylashishi mumkin. Bu kompozitsiya prinsipi. Asosiy ilova App komponenti bo''lib, uning ichida Header, Main, Footer komponentlari bo''lishi mumkin. Har bir komponent o''z mas''uliyatiga ega.

useEffect hook side effect lar uchun ishlatiladi: API chaqiruvi, eventListener qo''shish, timer. Dependency array orqali qachon ishga tushishini boshqarsamiz. Bo''sh massiv [] berilsa, faqat bir marta — komponent yuklanganda ishlaydi.', '2026-06-12 15:38:00');
INSERT INTO evaluations (lesson_id, overall_score, topic_score, speech_score, method_score, interaction_score, feedback_score, summary, strengths, improvements, advice, created_at) VALUES (1160, 64, 13, 11, 13, 12, 15, 'O''rtacha sifatdagi dars — mavzu qamrab olindi, lekin o''quvchilar reaktsiyasiga ko''p e''tibor berilmadi.', '["Misollar amaliy va o''quvchilarga tushunarli.","Vizual yoki yozma misollar kontsentratsiyaga yordam berdi."]', '["Murakkab atamalar uchun qisqacha takror berib turish foydali.","O''quvchilarga savollar berib qatnashtirish keng bo''lishi kerak."]', '["Muhim atamalarni taxtaga yozib qo''yish — eslab qolishni osonlashtiradi.","Tinglovchilarga 5-7 daqiqada bir savol berish — diqqatni saqlaydi.","Uy vazifasi sifatida 2-3 ta savol berish va keyingi darsda ko''rib chiqish."]', '2026-06-12 15:38:00');
