INSERT INTO evaluations (lesson_id, overall_score, topic_score, speech_score, method_score, interaction_score, feedback_score, summary, strengths, improvements, advice, created_at) VALUES (1165, 57, 14, 10, 12, 9, 12, 'Tushuntirish nomuvofiq, ba''zi muhim joylar o''tkazib yuborildi.', '["Tushunchalar bosqichma-bosqich oddiydan murakkabga qarab tushuntirildi.","Ovoz baland va aniq, jaranglashi yaxshi."]', '["Tushuntirish boshlanishida darsning maqsadi aniq aytilishi kerak.","Ko''proq amaliy mashqlar berilsa yaxshi bo''lardi.","Yozma misollarni daftar yoki taxta orqali ko''rsatish."]', '["Har dars boshida 1-2 daqiqa o''tgan darsni qaytarish — yaxshi natija beradi.","Tinglovchilarga 5-7 daqiqada bir savol berish — diqqatni saqlaydi."]', '2026-07-22 15:47:00');
INSERT INTO lessons (id, user_id, group_name, topic, course_type, duration_seconds, transcript, created_at) VALUES (1166, 1002, 'DI-201', 'VD — Asosiy tushunchalar', 'Veb dasturlash', 1417, 'Bugun biz HTTP protokolining asoslarini ko''rib chiqamiz. HTTP — bu mijoz va server o''rtasidagi muloqot tili. Brauzer so''rov yuboradi, server javob beradi.

So''rovning uchta asosiy qismi bor: metod, URL, va headerlar. Eng ko''p ishlatiladigan metodlar: GET — ma''lumot olish, POST — yangi ma''lumot yuborish, PUT — yangilash, DELETE — o''chirish. Bularning to''plami RESTful API ning asosini tashkil qiladi.

Status kodlar javobning natijasini bildiradi. 200 — muvaffaqiyat, 201 — yaratildi, 404 — topilmadi, 401 — autentifikatsiya kerak, 500 — server xatosi. Yaxshi API har doim to''g''ri status kod qaytarishi shart.

Bugun amaliy mashq sifatida fetch funksiyasi orqali oddiy API''dan ma''lumot olib, sahifada ko''rsatamiz. JSON formati zamonaviy veb da standart hisoblanadi.', '2026-07-20 12:15:00');
INSERT INTO evaluations (lesson_id, overall_score, topic_score, speech_score, method_score, interaction_score, feedback_score, summary, strengths, improvements, advice, created_at) VALUES (1166, 92, 19, 20, 20, 18, 15, 'Mazmun va shaklning yaxshi muvozanati. Misollar mavzuni qo''llab-quvvatlaydi.', '["Ovoz baland va aniq, jaranglashi yaxshi.","Mavzu aniq va izchil yoritildi."]', '["O''quvchilarga savollar berib qatnashtirish keng bo''lishi kerak.","Tushuntirish boshlanishida darsning maqsadi aniq aytilishi kerak.","Yozma misollarni daftar yoki taxta orqali ko''rsatish."]', '["Darsda Q&A vaqti aniq belgilash — talabalar savol berishdan tortinmasin.","Muhim atamalarni taxtaga yozib qo''yish — eslab qolishni osonlashtiradi.","Tinglovchilarga 5-7 daqiqada bir savol berish — diqqatni saqlaydi."]', '2026-07-20 12:15:00');
INSERT INTO lessons (id, user_id, group_name, topic, course_type, duration_seconds, transcript, created_at) VALUES (1167, 1002, 'DI-201', 'VD — Misollar va tahlil', 'Veb dasturlash', 912, 'React komponentlari haqida gaplashamiz. Komponent — bu UI ning qayta ishlatiladigan qismi. Function komponent eng zamonaviy yondashuv hisoblanadi.

