INSERT INTO evaluations (lesson_id, overall_score, topic_score, speech_score, method_score, interaction_score, feedback_score, summary, strengths, improvements, advice, created_at) VALUES (1170, 59, 12, 12, 13, 12, 10, 'Dars sxematik o''tdi — o''quvchilar bilan muloqot deyarli yo''q edi.', '["O''quvchilar bilan o''zaro muloqot yaxshi tashkil etilgan.","Mavzu aniq va izchil yoritildi.","O''qituvchi savollarga aniq javob berdi."]', '["Dars oxirida qisqa xulosa va kalit fikrlarni qaytarish.","Tushuntirish boshlanishida darsning maqsadi aniq aytilishi kerak.","Ko''proq amaliy mashqlar berilsa yaxshi bo''lardi."]', '["Eng oddiy misoldan boshlab keyingi qadamga o''tish — barcha o''quvchilar bilan bir tezlikda yurishga yordam beradi.","Muhim atamalarni taxtaga yozib qo''yish — eslab qolishni osonlashtiradi.","Real loyiha yoki amaliy vazifa qo''shish — motivatsiyani oshiradi."]', '2026-05-28 09:22:00');
INSERT INTO lessons (id, user_id, group_name, topic, course_type, duration_seconds, transcript, created_at) VALUES (1171, 1003, 'DI-102', 'MD — Loyiha taqdimoti', 'Mobil dasturlash', 2287, 'Android Compose — bu zamonaviy UI yaratish texnologiyasi. XML layout o''rniga biz Kotlin tilida deklarativ tarzda interfeysni tasvirlaymiz.

@Composable annotatsiyasi orqali funksiyalar yaratamiz. Misol: Text("Salom"), Button(onClick = ...), Column { Text(...); Text(...) }. State o''zgartirilganda UI avtomatik qayta render bo''ladi.

Modifier orqali ko''rinishni o''zgartiramiz: padding, background, clickable. Modifier zanjiri tartibi muhim — masalan padding(16.dp).background(Red) va background(Red).padding(16.dp) farqli natija beradi.

remember va mutableStateOf state boshqarish uchun. var count by remember mutableStateOf(0) — bu o''zgartirilganda UI yangilanadi. Ko''p ishlatiladigan pattern: Hoist state up, ya''ni state ni yuqori komponentga ko''chirish.', '2026-07-21 17:07:00');
INSERT INTO evaluations (lesson_id, overall_score, topic_score, speech_score, method_score, interaction_score, feedback_score, summary, strengths, improvements, advice, created_at) VALUES (1171, 87, 16, 15, 19, 18, 19, 'Mazmun va shaklning yaxshi muvozanati. Misollar mavzuni qo''llab-quvvatlaydi.', '["Misollar amaliy va o''quvchilarga tushunarli.","Ovoz baland va aniq, jaranglashi yaxshi.","Vizual yoki yozma misollar kontsentratsiyaga yordam berdi."]', '["Tushuntirish boshlanishida darsning maqsadi aniq aytilishi kerak.","Tezlikni biroz pasaytirish — ayrim joylar tez o''tib ketdi.","Ko''proq amaliy mashqlar berilsa yaxshi bo''lardi."]', '["Real loyiha yoki amaliy vazifa qo''shish — motivatsiyani oshiradi.","Tinglovchilarga 5-7 daqiqada bir savol berish — diqqatni saqlaydi.","Darsda Q&A vaqti aniq belgilash — talabalar savol berishdan tortinmasin."]', '2026-07-21 17:07:00');
