INSERT INTO evaluations (lesson_id, overall_score, topic_score, speech_score, method_score, interaction_score, feedback_score, summary, strengths, improvements, advice, created_at) VALUES (1177, 76, 15, 16, 14, 15, 16, 'Dars umumiy ma''noda yaxshi olib borildi, lekin amaliy qism va o''quvchilarni jalb qilish kuchaytirilishi kerak.', '["O''qituvchi savollarga aniq javob berdi.","Misollar amaliy va o''quvchilarga tushunarli."]', '["Yozma misollarni daftar yoki taxta orqali ko''rsatish.","Murakkab atamalar uchun qisqacha takror berib turish foydali.","Ko''proq amaliy mashqlar berilsa yaxshi bo''lardi."]', '["Tinglovchilarga 5-7 daqiqada bir savol berish — diqqatni saqlaydi.","Har dars boshida 1-2 daqiqa o''tgan darsni qaytarish — yaxshi natija beradi.","Uy vazifasi sifatida 2-3 ta savol berish va keyingi darsda ko''rib chiqish."]', '2026-06-03 15:51:00');
