INSERT INTO evaluations (lesson_id, overall_score, topic_score, speech_score, method_score, interaction_score, feedback_score, summary, strengths, improvements, advice, created_at) VALUES (1181, 73, 15, 15, 12, 15, 16, 'O''rtacha sifatdagi dars — mavzu qamrab olindi, lekin o''quvchilar reaktsiyasiga ko''p e''tibor berilmadi.', '["O''quvchilar bilan o''zaro muloqot yaxshi tashkil etilgan.","Misollar amaliy va o''quvchilarga tushunarli.","Real hayotdagi misollar yordamida nazariya mustahkamlandi."]', '["Dars oxirida qisqa xulosa va kalit fikrlarni qaytarish.","Ko''proq amaliy mashqlar berilsa yaxshi bo''lardi."]', '["Darsda Q&A vaqti aniq belgilash — talabalar savol berishdan tortinmasin.","Eng oddiy misoldan boshlab keyingi qadamga o''tish — barcha o''quvchilar bilan bir tezlikda yurishga yordam beradi."]', '2026-07-02 09:04:00');
INSERT INTO lessons (id, user_id, group_name, topic, course_type, duration_seconds, transcript, created_at) VALUES (1182, 1004, 'MA-201', 'SIA — Takrorlash va xulosa', 'Sun''iy intellekt asoslari', 1236, 'Sun''iy intellekt nima va nima emas? Bugun biz aniq belgilab olamiz. AI — bu kompyuter sistemalari odam aql talab qiladigan vazifalarni bajarishi. Lekin bu film kabi sezuvchi mavjudot emas.

AI ning uch katta turi bor: tor AI (narrow) — bitta vazifani bajaruvchi, masalan shaxmat dasturi yoki yuzni tanish. Umumiy AI (AGI) — odam kabi har xil vazifalarni bajarish, hozircha mavjud emas. Super AI — odamdan o''tib ketish, faqat fantastikada.

Bugungi barcha mashhur tizimlar — ChatGPT, Gemini, Midjourney — tor AI. Ular ma''lum vazifaga juda yaxshi javob beradi, lekin tushunish va ong yo''q. Asosida statistika va naqshlarni topish.

Mashinaviy o''rganish — bu AI ni yaratishning asosiy yo''li. Dasturchi qoidalarni yozmaydi, balki misollar beradi va sistema o''zi naqshni topadi. Keyingi darsda biz neyron tarmoqlar haqida gaplashamiz.', '2026-05-27 08:49:00');
