INSERT INTO evaluations (lesson_id, overall_score, topic_score, speech_score, method_score, interaction_score, feedback_score, summary, strengths, improvements, advice, created_at) VALUES (1187, 67, 16, 13, 12, 12, 14, 'Asosiy mavzu yetkazildi, lekin tushuntirishda ba''zi joylar tezroq o''tib ketdi.', '["Mavzu aniq va izchil yoritildi.","Tushunchalar bosqichma-bosqich oddiydan murakkabga qarab tushuntirildi.","O''quvchilar bilan o''zaro muloqot yaxshi tashkil etilgan."]', '["Yozma misollarni daftar yoki taxta orqali ko''rsatish.","O''quvchilarga savollar berib qatnashtirish keng bo''lishi kerak."]', '["Muhim atamalarni taxtaga yozib qo''yish — eslab qolishni osonlashtiradi.","Eng oddiy misoldan boshlab keyingi qadamga o''tish — barcha o''quvchilar bilan bir tezlikda yurishga yordam beradi."]', '2026-06-02 15:32:00');
INSERT INTO lessons (id, user_id, group_name, topic, course_type, duration_seconds, transcript, created_at) VALUES (1188, 1004, 'MA-201', 'SIA — Asosiy tushunchalar', 'Sun''iy intellekt asoslari', 3071, 'Sun''iy intellekt nima va nima emas? Bugun biz aniq belgilab olamiz. AI — bu kompyuter sistemalari odam aql talab qiladigan vazifalarni bajarishi. Lekin bu film kabi sezuvchi mavjudot emas.

AI ning uch katta turi bor: tor AI (narrow) — bitta vazifani bajaruvchi, masalan shaxmat dasturi yoki yuzni tanish. Umumiy AI (AGI) — odam kabi har xil vazifalarni bajarish, hozircha mavjud emas. Super AI — odamdan o''tib ketish, faqat fantastikada.

Bugungi barcha mashhur tizimlar — ChatGPT, Gemini, Midjourney — tor AI. Ular ma''lum vazifaga juda yaxshi javob beradi, lekin tushunish va ong yo''q. Asosida statistika va naqshlarni topish.

Mashinaviy o''rganish — bu AI ni yaratishning asosiy yo''li. Dasturchi qoidalarni yozmaydi, balki misollar beradi va sistema o''zi naqshni topadi. Keyingi darsda biz neyron tarmoqlar haqida gaplashamiz.', '2026-06-06 10:44:00');
INSERT INTO evaluations (lesson_id, overall_score, topic_score, speech_score, method_score, interaction_score, feedback_score, summary, strengths, improvements, advice, created_at) VALUES (1188, 66, 14, 14, 14, 13, 11, 'Dars umumiy ma''noda yaxshi olib borildi, lekin amaliy qism va o''quvchilarni jalb qilish kuchaytirilishi kerak.', '["Misollar amaliy va o''quvchilarga tushunarli.","Ovoz baland va aniq, jaranglashi yaxshi.","O''quvchilar bilan o''zaro muloqot yaxshi tashkil etilgan."]', '["Tezlikni biroz pasaytirish — ayrim joylar tez o''tib ketdi.","Dars oxirida qisqa xulosa va kalit fikrlarni qaytarish.","Ko''proq amaliy mashqlar berilsa yaxshi bo''lardi."]', '["Tinglovchilarga 5-7 daqiqada bir savol berish — diqqatni saqlaydi.","Darsda Q&A vaqti aniq belgilash — talabalar savol berishdan tortinmasin.","Eng oddiy misoldan boshlab keyingi qadamga o''tish — barcha o''quvchilar bilan bir tezlikda yurishga yordam beradi."]', '2026-06-06 10:44:00');
INSERT INTO lessons (id, user_id, group_name, topic, course_type, duration_seconds, transcript, created_at) VALUES (1189, 1005, 'DI-301', 'MO — Yangi mavzu kirishi', 'Mashinaviy o''rganish', 3874, 'Linear regressiya — eng oddiy va eng asosiy ML algoritm. Maqsadi: kirish (X) va chiqish (y) o''rtasidagi chiziqli bog''liqlikni topish.

Formula: y = wx + b. Bu yerda w og''irlik (slope), b bias (intercept). Ma''lumotlar asosida w va b qiymatlarini topishimiz kerak. Bu uchun yo''qotish funksiyasini (loss function) minimallashtiramiz.

Eng ko''p ishlatiladigan loss — Mean Squared Error: barcha xatolarning kvadratlari o''rtachasi. Gradient descent algoritmi bilan loss ni kamaytiramiz, har qadamda w va b ni biroz o''zgartiramiz.

scikit-learn kutubxonasi bilan amalga oshirish juda oson: from sklearn.linear_model import LinearRegression, model = LinearRegression(), model.fit(X, y). Lekin asosini tushunish muhim — boshqa algoritmlar shu printsipga asoslangan.', '2026-07-22 12:04:00');
INSERT INTO evaluations (lesson_id, overall_score, topic_score, speech_score, method_score, interaction_score, feedback_score, summary, strengths, improvements, advice, created_at) VALUES (1189, 66, 12, 14, 12, 12, 16, 'Dars umumiy ma''noda yaxshi olib borildi, lekin amaliy qism va o''quvchilarni jalb qilish kuchaytirilishi kerak.', '["Tushunchalar bosqichma-bosqich oddiydan murakkabga qarab tushuntirildi.","Vizual yoki yozma misollar kontsentratsiyaga yordam berdi.","Misollar amaliy va o''quvchilarga tushunarli."]', '["Tezlikni biroz pasaytirish — ayrim joylar tez o''tib ketdi.","Dars oxirida qisqa xulosa va kalit fikrlarni qaytarish."]', '["Uy vazifasi sifatida 2-3 ta savol berish va keyingi darsda ko''rib chiqish.","Real loyiha yoki amaliy vazifa qo''shish — motivatsiyani oshiradi."]', '2026-07-22 12:04:00');
