INSERT INTO evaluations (lesson_id, overall_score, topic_score, speech_score, method_score, interaction_score, feedback_score, summary, strengths, improvements, advice, created_at) VALUES (1198, 67, 13, 12, 16, 11, 15, 'Asosiy mavzu yetkazildi, lekin tushuntirishda ba''zi joylar tezroq o''tib ketdi.', '["Mavzu aniq va izchil yoritildi.","Real hayotdagi misollar yordamida nazariya mustahkamlandi."]', '["Tezlikni biroz pasaytirish — ayrim joylar tez o''tib ketdi.","Dars oxirida qisqa xulosa va kalit fikrlarni qaytarish."]', '["Muhim atamalarni taxtaga yozib qo''yish — eslab qolishni osonlashtiradi.","Real loyiha yoki amaliy vazifa qo''shish — motivatsiyani oshiradi.","Uy vazifasi sifatida 2-3 ta savol berish va keyingi darsda ko''rib chiqish."]', '2026-05-31 16:55:00');
INSERT INTO lessons (id, user_id, group_name, topic, course_type, duration_seconds, transcript, created_at) VALUES (1199, 1005, 'DI-202', 'MO — Takrorlash va xulosa', 'Mashinaviy o''rganish', 3815, 'Linear regressiya — eng oddiy va eng asosiy ML algoritm. Maqsadi: kirish (X) va chiqish (y) o''rtasidagi chiziqli bog''liqlikni topish.

