scikit-learn kutubxonasi bilan amalga oshirish juda oson: from sklearn.linear_model import LinearRegression, model = LinearRegression(), model.fit(X, y). Lekin asosini tushunish muhim — boshqa algoritmlar shu printsipga asoslangan.', '2026-06-13 12:11:00');
INSERT INTO evaluations (lesson_id, overall_score, topic_score, speech_score, method_score, interaction_score, feedback_score, summary, strengths, improvements, advice, created_at) VALUES (1199, 74, 16, 13, 15, 16, 14, 'O''rtacha sifatdagi dars — mavzu qamrab olindi, lekin o''quvchilar reaktsiyasiga ko''p e''tibor berilmadi.', '["Misollar amaliy va o''quvchilarga tushunarli.","Tushunchalar bosqichma-bosqich oddiydan murakkabga qarab tushuntirildi."]', '["Ko''proq amaliy mashqlar berilsa yaxshi bo''lardi.","Yozma misollarni daftar yoki taxta orqali ko''rsatish.","Dars oxirida qisqa xulosa va kalit fikrlarni qaytarish."]', '["Real loyiha yoki amaliy vazifa qo''shish — motivatsiyani oshiradi.","Eng oddiy misoldan boshlab keyingi qadamga o''tish — barcha o''quvchilar bilan bir tezlikda yurishga yordam beradi.","Uy vazifasi sifatida 2-3 ta savol berish va keyingi darsda ko''rib chiqish."]', '2026-06-13 12:11:00');
