INSERT INTO evaluations (lesson_id, overall_score, topic_score, speech_score, method_score, interaction_score, feedback_score, summary, strengths, improvements, advice, created_at) VALUES (1202, 87, 17, 18, 18, 19, 15, 'Dars yaxshi tashkil etilgan, mavzu chuqur va aniq yoritilgan. O''quvchilar bilan muloqot mustahkam.', '["Ovoz baland va aniq, jaranglashi yaxshi.","Real hayotdagi misollar yordamida nazariya mustahkamlandi."]', '["Tezlikni biroz pasaytirish — ayrim joylar tez o''tib ketdi.","Murakkab atamalar uchun qisqacha takror berib turish foydali.","Yozma misollarni daftar yoki taxta orqali ko''rsatish."]', '["Real loyiha yoki amaliy vazifa qo''shish — motivatsiyani oshiradi.","Uy vazifasi sifatida 2-3 ta savol berish va keyingi darsda ko''rib chiqish."]', '2026-06-06 12:35:00');
