INSERT INTO lessons (id, user_id, group_name, topic, course_type, duration_seconds, transcript, created_at) VALUES (1208, 1007, 'RI-201', 'DM — Takrorlash va xulosa', 'Diskret matematika', 3867, 'Bugungi mavzu — to''plamlar va ulardagi amallar. To''plam — bu aniq belgilangan obyektlar yig''indisi. A = {1, 2, 3} kabi yoziladi. Element to''plamga tegishli yoki tegishli emas.

Asosiy amallar: birlashma (A∪B) — barcha elementlar; kesishma (A∩B) — umumiy elementlar; ayirma (A\B) — A da bor lekin B da yo''q; to''ldiruvchi — universal to''plamdagi qolganlar.

Kuchli to''plam (power set) — berilgan to''plamning barcha qism to''plamlari to''plami. Agar A = {a, b} bo''lsa, P(A) = {∅, {a}, {b}, {a,b}}. Ya''ni 2^n ta element bo''ladi.

Vennin diagrammasi to''plam munosabatlarini vizualizatsiya qilish uchun ajoyib vosita. Ikki yoki uchta to''plam uchun yaxshi ishlaydi. Mantiqiy fikrlashda ham qo''l keladi: "barcha A — B" degani A ⊆ B.', '2026-06-01 16:40:00');
INSERT INTO evaluations (lesson_id, overall_score, topic_score, speech_score, method_score, interaction_score, feedback_score, summary, strengths, improvements, advice, created_at) VALUES (1208, 77, 18, 13, 16, 13, 17, 'Asosiy mavzu yetkazildi, lekin tushuntirishda ba''zi joylar tezroq o''tib ketdi.', '["O''quvchilar bilan o''zaro muloqot yaxshi tashkil etilgan.","Real hayotdagi misollar yordamida nazariya mustahkamlandi.","Ovoz baland va aniq, jaranglashi yaxshi."]', '["Tushuntirish boshlanishida darsning maqsadi aniq aytilishi kerak.","Tezlikni biroz pasaytirish — ayrim joylar tez o''tib ketdi.","Murakkab atamalar uchun qisqacha takror berib turish foydali."]', '["Real loyiha yoki amaliy vazifa qo''shish — motivatsiyani oshiradi.","Eng oddiy misoldan boshlab keyingi qadamga o''tish — barcha o''quvchilar bilan bir tezlikda yurishga yordam beradi.","Tinglovchilarga 5-7 daqiqada bir savol berish — diqqatni saqlaydi."]', '2026-06-01 16:40:00');
