INSERT INTO evaluations (lesson_id, overall_score, topic_score, speech_score, method_score, interaction_score, feedback_score, summary, strengths, improvements, advice, created_at) VALUES (1210, 72, 14, 12, 17, 14, 15, 'Dars umumiy ma''noda yaxshi olib borildi, lekin amaliy qism va o''quvchilarni jalb qilish kuchaytirilishi kerak.', '["Tushunchalar bosqichma-bosqich oddiydan murakkabga qarab tushuntirildi.","Ovoz baland va aniq, jaranglashi yaxshi."]', '["Yozma misollarni daftar yoki taxta orqali ko''rsatish.","Tushuntirish boshlanishida darsning maqsadi aniq aytilishi kerak.","Dars oxirida qisqa xulosa va kalit fikrlarni qaytarish."]', '["Real loyiha yoki amaliy vazifa qo''shish — motivatsiyani oshiradi.","Darsda Q&A vaqti aniq belgilash — talabalar savol berishdan tortinmasin."]', '2026-07-01 15:38:00');
