INSERT INTO evaluations (lesson_id, overall_score, topic_score, speech_score, method_score, interaction_score, feedback_score, summary, strengths, improvements, advice, created_at) VALUES (1211, 80, 16, 14, 16, 19, 15, 'Pedagogik jihatdan kuchli dars. Kichik takomillashtirishlar bilan a''lo bo''lishi mumkin.', '["Mavzu aniq va izchil yoritildi.","Real hayotdagi misollar yordamida nazariya mustahkamlandi.","O''qituvchi savollarga aniq javob berdi."]', '["Tushuntirish boshlanishida darsning maqsadi aniq aytilishi kerak.","Murakkab atamalar uchun qisqacha takror berib turish foydali.","Ko''proq amaliy mashqlar berilsa yaxshi bo''lardi."]', '["Real loyiha yoki amaliy vazifa qo''shish — motivatsiyani oshiradi.","Darsda Q&A vaqti aniq belgilash — talabalar savol berishdan tortinmasin."]', '2026-05-25 12:24:00');
