INSERT INTO evaluations (lesson_id, overall_score, topic_score, speech_score, method_score, interaction_score, feedback_score, summary, strengths, improvements, advice, created_at) VALUES (1215, 57, 10, 10, 13, 9, 15, 'Dars sxematik o''tdi — o''quvchilar bilan muloqot deyarli yo''q edi.', '["O''quvchilar bilan o''zaro muloqot yaxshi tashkil etilgan.","Real hayotdagi misollar yordamida nazariya mustahkamlandi.","Misollar amaliy va o''quvchilarga tushunarli."]', '["Dars oxirida qisqa xulosa va kalit fikrlarni qaytarish.","O''quvchilarga savollar berib qatnashtirish keng bo''lishi kerak.","Tushuntirish boshlanishida darsning maqsadi aniq aytilishi kerak."]', '["Real loyiha yoki amaliy vazifa qo''shish — motivatsiyani oshiradi.","Tinglovchilarga 5-7 daqiqada bir savol berish — diqqatni saqlaydi."]', '2026-07-07 15:34:00');
