INSERT INTO lessons (id, user_id, group_name, topic, course_type, duration_seconds, transcript, created_at) VALUES (1220, 1007, 'DI-201', 'DM — Test va o''zlashtirish', 'Diskret matematika', 2692, 'Bugungi mavzu — to''plamlar va ulardagi amallar. To''plam — bu aniq belgilangan obyektlar yig''indisi. A = {1, 2, 3} kabi yoziladi. Element to''plamga tegishli yoki tegishli emas.

Asosiy amallar: birlashma (A∪B) — barcha elementlar; kesishma (A∩B) — umumiy elementlar; ayirma (A\B) — A da bor lekin B da yo''q; to''ldiruvchi — universal to''plamdagi qolganlar.

Kuchli to''plam (power set) — berilgan to''plamning barcha qism to''plamlari to''plami. Agar A = {a, b} bo''lsa, P(A) = {∅, {a}, {b}, {a,b}}. Ya''ni 2^n ta element bo''ladi.

Vennin diagrammasi to''plam munosabatlarini vizualizatsiya qilish uchun ajoyib vosita. Ikki yoki uchta to''plam uchun yaxshi ishlaydi. Mantiqiy fikrlashda ham qo''l keladi: "barcha A — B" degani A ⊆ B.', '2026-06-14 08:22:00');
INSERT INTO evaluations (lesson_id, overall_score, topic_score, speech_score, method_score, interaction_score, feedback_score, summary, strengths, improvements, advice, created_at) VALUES (1220, 72, 13, 18, 16, 12, 13, 'O''rtacha sifatdagi dars — mavzu qamrab olindi, lekin o''quvchilar reaktsiyasiga ko''p e''tibor berilmadi.', '["Vizual yoki yozma misollar kontsentratsiyaga yordam berdi.","O''qituvchi savollarga aniq javob berdi.","Real hayotdagi misollar yordamida nazariya mustahkamlandi."]', '["Yozma misollarni daftar yoki taxta orqali ko''rsatish.","Ko''proq amaliy mashqlar berilsa yaxshi bo''lardi."]', '["Uy vazifasi sifatida 2-3 ta savol berish va keyingi darsda ko''rib chiqish.","Real loyiha yoki amaliy vazifa qo''shish — motivatsiyani oshiradi.","Tinglovchilarga 5-7 daqiqada bir savol berish — diqqatni saqlaydi."]', '2026-06-14 08:22:00');
INSERT INTO lessons (id, user_id, group_name, topic, course_type, duration_seconds, transcript, created_at) VALUES (1221, 1008, 'DI-301', 'IN — Misollar va tahlil', 'Iqtisodiyot nazariyasi', 3419, 'Talab va taklif qonuni — bozor iqtisodiyotining asosi. Talab — xaridorlar ma''lum narxda sotib olishga tayyor bo''lgan miqdor. Taklif — sotuvchilar shu narxda sotishga tayyor miqdor.

Narx oshganda talab odatda kamayadi (ters proportsional). Taklif esa oshadi — sotuvchilar ko''proq daromad olish uchun ko''proq taklif qiladilar. Ikkala chiziq kesishgan nuqta — muvozanat narxi.

Elastiklik — narx o''zgarganda talab qancha o''zgarishini ko''rsatadi. Asosiy mahsulotlar (non, suv) noelastik — narx oshsa ham deyarli xuddi shuncha sotib olinadi. Hashamatli mollar elastik.

Davlat narxlarni belgilashi mumkin: maksimum (tomon) yoki minimum (yer). Lekin bu ko''pincha tanqislikni yoki ortiqcha taklifni keltirib chiqaradi. Erkin bozor odatda samaraliroq, lekin nazoratsiz qoldirish ham xavfli.', '2026-07-22 10:14:00');
INSERT INTO evaluations (lesson_id, overall_score, topic_score, speech_score, method_score, interaction_score, feedback_score, summary, strengths, improvements, advice, created_at) VALUES (1221, 84, 15, 17, 15, 20, 17, 'Mazmun va shaklning yaxshi muvozanati. Misollar mavzuni qo''llab-quvvatlaydi.', '["Mavzu aniq va izchil yoritildi.","Real hayotdagi misollar yordamida nazariya mustahkamlandi.","Misollar amaliy va o''quvchilarga tushunarli."]', '["O''quvchilarga savollar berib qatnashtirish keng bo''lishi kerak.","Tezlikni biroz pasaytirish — ayrim joylar tez o''tib ketdi.","Yozma misollarni daftar yoki taxta orqali ko''rsatish."]', '["Darsda Q&A vaqti aniq belgilash — talabalar savol berishdan tortinmasin.","Eng oddiy misoldan boshlab keyingi qadamga o''tish — barcha o''quvchilar bilan bir tezlikda yurishga yordam beradi.","Uy vazifasi sifatida 2-3 ta savol berish va keyingi darsda ko''rib chiqish."]', '2026-07-22 10:14:00');
