INSERT INTO evaluations (lesson_id, overall_score, topic_score, speech_score, method_score, interaction_score, feedback_score, summary, strengths, improvements, advice, created_at) VALUES (1222, 91, 18, 20, 19, 19, 15, 'Mazmun va shaklning yaxshi muvozanati. Misollar mavzuni qo''llab-quvvatlaydi.', '["Tushunchalar bosqichma-bosqich oddiydan murakkabga qarab tushuntirildi.","Misollar amaliy va o''quvchilarga tushunarli."]', '["Ko''proq amaliy mashqlar berilsa yaxshi bo''lardi.","O''quvchilarga savollar berib qatnashtirish keng bo''lishi kerak.","Murakkab atamalar uchun qisqacha takror berib turish foydali."]', '["Darsda Q&A vaqti aniq belgilash — talabalar savol berishdan tortinmasin.","Har dars boshida 1-2 daqiqa o''tgan darsni qaytarish — yaxshi natija beradi."]', '2026-05-27 09:37:00');
