INSERT INTO evaluations (lesson_id, overall_score, topic_score, speech_score, method_score, interaction_score, feedback_score, summary, strengths, improvements, advice, created_at) VALUES (1230, 78, 14, 18, 17, 14, 15, 'O''rtacha sifatdagi dars — mavzu qamrab olindi, lekin o''quvchilar reaktsiyasiga ko''p e''tibor berilmadi.', '["Vizual yoki yozma misollar kontsentratsiyaga yordam berdi.","Tushunchalar bosqichma-bosqich oddiydan murakkabga qarab tushuntirildi.","Real hayotdagi misollar yordamida nazariya mustahkamlandi."]', '["Murakkab atamalar uchun qisqacha takror berib turish foydali.","Yozma misollarni daftar yoki taxta orqali ko''rsatish."]', '["Muhim atamalarni taxtaga yozib qo''yish — eslab qolishni osonlashtiradi.","Real loyiha yoki amaliy vazifa qo''shish — motivatsiyani oshiradi.","Uy vazifasi sifatida 2-3 ta savol berish va keyingi darsda ko''rib chiqish."]', '2026-06-20 13:03:00');
INSERT INTO lessons (id, user_id, group_name, topic, course_type, duration_seconds, transcript, created_at) VALUES (1231, 1008, 'DI-102', 'IN — Yechimlar muhokamasi', 'Iqtisodiyot nazariyasi', 1791, 'Talab va taklif qonuni — bozor iqtisodiyotining asosi. Talab — xaridorlar ma''lum narxda sotib olishga tayyor bo''lgan miqdor. Taklif — sotuvchilar shu narxda sotishga tayyor miqdor.

Narx oshganda talab odatda kamayadi (ters proportsional). Taklif esa oshadi — sotuvchilar ko''proq daromad olish uchun ko''proq taklif qiladilar. Ikkala chiziq kesishgan nuqta — muvozanat narxi.

Elastiklik — narx o''zgarganda talab qancha o''zgarishini ko''rsatadi. Asosiy mahsulotlar (non, suv) noelastik — narx oshsa ham deyarli xuddi shuncha sotib olinadi. Hashamatli mollar elastik.

Davlat narxlarni belgilashi mumkin: maksimum (tomon) yoki minimum (yer). Lekin bu ko''pincha tanqislikni yoki ortiqcha taklifni keltirib chiqaradi. Erkin bozor odatda samaraliroq, lekin nazoratsiz qoldirish ham xavfli.', '2026-05-26 16:23:00');
INSERT INTO evaluations (lesson_id, overall_score, topic_score, speech_score, method_score, interaction_score, feedback_score, summary, strengths, improvements, advice, created_at) VALUES (1231, 60, 14, 10, 13, 13, 10, 'Asosiy mavzu yetkazildi, lekin tushuntirishda ba''zi joylar tezroq o''tib ketdi.', '["O''quvchilar bilan o''zaro muloqot yaxshi tashkil etilgan.","Misollar amaliy va o''quvchilarga tushunarli.","Mavzu aniq va izchil yoritildi."]', '["Tushuntirish boshlanishida darsning maqsadi aniq aytilishi kerak.","Tezlikni biroz pasaytirish — ayrim joylar tez o''tib ketdi."]', '["Har dars boshida 1-2 daqiqa o''tgan darsni qaytarish — yaxshi natija beradi.","Real loyiha yoki amaliy vazifa qo''shish — motivatsiyani oshiradi.","Darsda Q&A vaqti aniq belgilash — talabalar savol berishdan tortinmasin."]', '2026-05-26 16:23:00');
INSERT INTO lessons (id, user_id, group_name, topic, course_type, duration_seconds, transcript, created_at) VALUES (1232, 1009, 'DI-102', 'LB — Yangi mavzu kirishi', 'Loyihalarni boshqarish', 3560, 'Agile metodologiyasi — bu loyihalarni iterativ tarzda boshqarish yondashuvi. Asoschi 2001-yilda 17 dasturchi yozgan Agile Manifesto.

Asosiy printsiplar: shaxslar va munosabatlar — jarayonlar va vositalardan muhim; ishlaydigan dastur — to''liq hujjatdan muhim; mijoz bilan hamkorlik — shartnomadan muhim; o''zgarishlarga moslashish — rejani qattiq amal qilishdan muhim.

Scrum — Agile ning eng mashhur amalga oshirilishi. Sprint deb ataladigan 2-4 haftalik sikllarda ishlaymiz. Har sprint oxirida ishlaydigan mahsulotning qismi tayyor bo''lishi kerak.

Asosiy rollar: Product Owner — nima qilish kerakligini aniqlaydi; Scrum Master — jarayonni boshqaradi; Development Team — qiladi. Daily standup, sprint planning, sprint review, retrospective — asosiy uchrashuvlar.', '2026-06-02 11:07:00');
INSERT INTO evaluations (lesson_id, overall_score, topic_score, speech_score, method_score, interaction_score, feedback_score, summary, strengths, improvements, advice, created_at) VALUES (1232, 76, 13, 15, 18, 12, 18, 'O''rtacha sifatdagi dars — mavzu qamrab olindi, lekin o''quvchilar reaktsiyasiga ko''p e''tibor berilmadi.', '["Ovoz baland va aniq, jaranglashi yaxshi.","Tushunchalar bosqichma-bosqich oddiydan murakkabga qarab tushuntirildi.","Mavzu aniq va izchil yoritildi."]', '["Tezlikni biroz pasaytirish — ayrim joylar tez o''tib ketdi.","Murakkab atamalar uchun qisqacha takror berib turish foydali."]', '["Tinglovchilarga 5-7 daqiqada bir savol berish — diqqatni saqlaydi.","Uy vazifasi sifatida 2-3 ta savol berish va keyingi darsda ko''rib chiqish."]', '2026-06-02 11:07:00');
