INSERT INTO mentor_chats (lesson_id, student_id, role, content, created_at) VALUES (1006, 1136, 'user', 'remember va rememberSaveable orasidagi farq?', '2026-06-22 19:23:00');
INSERT INTO mentor_chats (lesson_id, student_id, role, content, created_at) VALUES (1006, 1136, 'assistant', 'remember — recomposition oralig''ida state ni saqlaydi. rememberSaveable — bundan tashqari, configuration change (rotation) yoki process death dan keyin ham state ni qaytaradi.', '2026-06-22 19:23:00');
