INSERT INTO mentor_chats (lesson_id, student_id, role, content, created_at) VALUES (1018, 1125, 'user', 'Overfitting nima?', '2026-06-22 14:37:00');
INSERT INTO mentor_chats (lesson_id, student_id, role, content, created_at) VALUES (1018, 1125, 'assistant', 'Model o''qitish ma''lumotini juda yaxshi yodlab, yangi (ko''rilmagan) ma''lumotda yomon ishlashi. Yechimlar: ko''proq ma''lumot, modelni soddalashtirish, regularizatsiya, cross-validation.', '2026-06-22 14:37:00');
