INSERT INTO mentor_chats (lesson_id, student_id, role, content, created_at) VALUES (1080, 1130, 'user', 'ChatGPT qanday ishlaydi?', '2026-07-19 19:35:00');
INSERT INTO mentor_chats (lesson_id, student_id, role, content, created_at) VALUES (1080, 1130, 'assistant', 'ChatGPT — bu katta til modeli (LLM) bo''lib, milliardlab matnlarda o''qitilgan. U keyingi so''zni bashorat qilish orqali javob yaratadi. Ya''ni ''tushunish'' emas, statistik naqshlarga asoslangan.', '2026-07-19 19:35:00');
INSERT INTO mentor_chats (lesson_id, student_id, role, content, created_at) VALUES (1084, 1143, 'user', 'Kuchli to''plamda nima uchun 2^n element bo''ladi?', '2026-06-25 17:54:00');
INSERT INTO mentor_chats (lesson_id, student_id, role, content, created_at) VALUES (1084, 1143, 'assistant', 'Har bir element qism to''plamda yoki bor, yoki yo''q (2 variant). N ta element bo''lsa, 2 × 2 × ... × 2 (n marta) = 2^n ta turli kombinatsiya bo''ladi.', '2026-06-25 17:54:00');
