INSERT INTO mentor_chats (lesson_id, student_id, role, content, created_at) VALUES (1112, 1109, 'user', 'if va elif farqi nima?', '2026-05-28 20:24:00');
INSERT INTO mentor_chats (lesson_id, student_id, role, content, created_at) VALUES (1112, 1109, 'assistant', 'if — birinchi shart, elif — undan keyingi qo''shimcha shartlar. Misol uchun bahoni baholashda: if score >= 90 → ''a''lo'', elif score >= 70 → ''yaxshi'', else → ''qoniqarli''. Bittadan ortiq elif bo''lishi mumkin.', '2026-05-28 20:24:00');
INSERT INTO mentor_chats (lesson_id, student_id, role, content, created_at) VALUES (1112, 1133, 'user', 'Funksiyaga default argument qanday beriladi?', '2026-05-29 18:21:00');
INSERT INTO mentor_chats (lesson_id, student_id, role, content, created_at) VALUES (1112, 1133, 'assistant', 'Argument nomidan keyin teng belgisi va qiymat: `def salom(ism=''dunyo''):`. Endi funksiyani ism bermasdan chaqirsangiz, default ''dunyo'' ishlatiladi.', '2026-05-29 18:21:00');
