INSERT INTO mentor_chats (lesson_id, student_id, role, content, created_at) VALUES (1145, 1110, 'user', 'if va elif farqi nima?', '2026-05-30 22:21:00');
INSERT INTO mentor_chats (lesson_id, student_id, role, content, created_at) VALUES (1145, 1110, 'assistant', 'if — birinchi shart, elif — undan keyingi qo''shimcha shartlar. Misol uchun bahoni baholashda: if score >= 90 → ''a''lo'', elif score >= 70 → ''yaxshi'', else → ''qoniqarli''. Bittadan ortiq elif bo''lishi mumkin.', '2026-05-30 22:21:00');
