INSERT INTO mentor_chats (lesson_id, student_id, role, content, created_at) VALUES (1153, 1134, 'user', 'Nega O(n²) yomon?', '2026-07-19 21:34:00');
INSERT INTO mentor_chats (lesson_id, student_id, role, content, created_at) VALUES (1153, 1134, 'assistant', 'Kirish hajmi 10 marta oshsa, vaqt 100 marta oshadi. 1000 ta element 1 soniyada bajarilsa, 10000 ta element 100 soniya oladi. Shuning uchun katta ma''lumotda O(n log n) yoki O(n) algoritmlar kerak.', '2026-07-19 21:34:00');
INSERT INTO mentor_chats (lesson_id, student_id, role, content, created_at) VALUES (1153, 1158, 'user', 'Qachon stack ishlatilsa yaxshi?', '2026-07-17 16:13:00');
INSERT INTO mentor_chats (lesson_id, student_id, role, content, created_at) VALUES (1153, 1158, 'assistant', 'Oxirgi qo''shilgan elementga birinchi murojaat qilish kerak bo''lganda. Klassik misol: brauzerda ''back'' tugmasi, undo funksiyasi, qavslarni tekshirish, va rekursiyani simulyatsiya qilish.', '2026-07-17 16:13:00');
